


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "inventory";


ALTER SCHEMA "inventory" OWNER TO "postgres";


COMMENT ON SCHEMA "inventory" IS 'Event-driven inventory management system.
    
    PARTITIONING STRATEGY:
    - inventory_events: PARTITION BY RANGE (occurred_at) - monthly partitions
    - stock_movements: PARTITION BY RANGE (occurred_at) - monthly partitions  
    - daily_item_activity: PARTITION BY RANGE (activity_date) - yearly partitions
    
    Implement partitioning when tables exceed 10M rows.
    
    MAINTENANCE SCHEDULE:
    - Materialized views: Refresh every 5 minutes (via cron/scheduler)
    - VACUUM ANALYZE: Automatic via autovacuum, monitor with v_table_bloat
    - Old partitions: Archive/drop partitions older than 2 years
    
    PERFORMANCE MONITORING:
    - pg_stat_statements enabled for query analysis
    - v_slow_queries: Review weekly
    - v_table_bloat: Monitor dead tuple percentage > 20%
    - v_events_stuck: Alert on health_status != OK';



COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE SCHEMA IF NOT EXISTS "supply_chain";


ALTER SCHEMA "supply_chain" OWNER TO "postgres";


COMMENT ON SCHEMA "supply_chain" IS 'Supply chain management schema - purchasing, vendors, receipts. Grants: anon=SELECT, authenticated=ALL';



CREATE EXTENSION IF NOT EXISTS "pg_graphql" WITH SCHEMA "graphql";






CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






CREATE OR REPLACE FUNCTION "inventory"."add_test_stock"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN inventory.insert_stock_movement(
        p_tenant_id => p_tenant_id,
        p_catalog_item_id => p_catalog_item_id,
        p_location_id => p_location_id,
        p_quantity_delta => p_qty,
        p_movement_type => 'received',
        p_source_ref_type => 'test_data',
        p_source_ref_id => NULL,
        p_unit_cost => 10.00,
        p_reason => 'Test data',
        p_notes => 'Generated by test helper',
        p_correlation_id => NULL,
        p_occurred_at => NOW(),
        p_created_by_user_id => NULL,
        p_last_event_id => 'test_stock_' || gen_random_uuid()::TEXT
    );
END;
$$;


ALTER FUNCTION "inventory"."add_test_stock"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."check_variance_approval"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_item_category_id" "uuid", "p_variance_qty" numeric, "p_expected_qty" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_threshold RECORD;
    v_variance_pct NUMERIC;
BEGIN
    -- Calculate variance percentage
    IF p_expected_qty = 0 THEN
        v_variance_pct := NULL;
    ELSE
        v_variance_pct := ABS((p_variance_qty / p_expected_qty) * 100);
    END IF;
    
    -- Find most specific threshold (priority order)
    SELECT * INTO v_threshold
    FROM inventory.cycle_count_variance_thresholds
    WHERE tenant_id = p_tenant_id
    AND (catalog_item_id = p_catalog_item_id OR catalog_item_id IS NULL)
    AND (location_id = p_location_id OR location_id IS NULL)
    AND (item_category_id = p_item_category_id OR item_category_id IS NULL)
    ORDER BY priority ASC
    LIMIT 1;
    
    -- If no threshold found, require approval for any variance
    IF NOT FOUND THEN
        RETURN (p_variance_qty != 0);
    END IF;
    
    -- Check thresholds
    IF v_threshold.max_variance_qty IS NOT NULL AND ABS(p_variance_qty) > v_threshold.max_variance_qty THEN
        RETURN TRUE;
    END IF;
    
    IF v_threshold.max_variance_pct IS NOT NULL AND v_variance_pct IS NOT NULL 
       AND v_variance_pct > v_threshold.max_variance_pct THEN
        RETURN TRUE;
    END IF;
    
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "inventory"."check_variance_approval"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_item_category_id" "uuid", "p_variance_qty" numeric, "p_expected_qty" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."check_variance_approval"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_item_category_id" "uuid", "p_variance_qty" numeric, "p_expected_qty" numeric) IS 'Determines if variance requires approval based on thresholds';



CREATE OR REPLACE FUNCTION "inventory"."create_test_item"("p_tenant_id" "uuid", "p_sku" "text" DEFAULT NULL::"text", "p_name" "text" DEFAULT NULL::"text", "p_item_type" "text" DEFAULT 'stock'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_item_id UUID;
    v_sku TEXT;
    v_name TEXT;
BEGIN
    v_sku := COALESCE(p_sku, 'TEST-' || substring(gen_random_uuid()::TEXT from 1 for 8));
    v_name := COALESCE(p_name, 'Test Item ' || v_sku);
    
    INSERT INTO inventory.catalog_items (
        tenant_id,
        sku,
        name,
        item_type,
        last_event_id
    )
    VALUES (
        p_tenant_id,
        v_sku,
        v_name,
        p_item_type,
        'test_item_' || gen_random_uuid()::TEXT
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_item_id;
    
    IF v_item_id IS NULL THEN
        SELECT id INTO v_item_id
        FROM inventory.catalog_items
        WHERE tenant_id = p_tenant_id
        AND sku = v_sku
        LIMIT 1;
    END IF;
    
    RETURN v_item_id;
END;
$$;


ALTER FUNCTION "inventory"."create_test_item"("p_tenant_id" "uuid", "p_sku" "text", "p_name" "text", "p_item_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."create_test_location"("p_tenant_id" "uuid", "p_location_name" "text" DEFAULT 'Test Warehouse'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_location_id UUID;
BEGIN
    INSERT INTO inventory.locations (
        tenant_id, 
        name, 
        location_type, 
        last_event_id
    )
    VALUES (
        p_tenant_id,
        p_location_name,
        'warehouse',
        'test_location_' || gen_random_uuid()::TEXT
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_location_id;
    
    IF v_location_id IS NULL THEN
        SELECT id INTO v_location_id
        FROM inventory.locations
        WHERE tenant_id = p_tenant_id
        AND name = p_location_name
        LIMIT 1;
    END IF;
    
    RETURN v_location_id;
END;
$$;


ALTER FUNCTION "inventory"."create_test_location"("p_tenant_id" "uuid", "p_location_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."create_test_tenant"("p_tenant_name" "text" DEFAULT 'Test Tenant'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
BEGIN
    INSERT INTO public.tenants (name, last_event_id)
    VALUES (p_tenant_name, 'test_tenant_' || gen_random_uuid()::TEXT)
    ON CONFLICT (last_event_id) DO NOTHING
    RETURNING id INTO v_tenant_id;
    
    IF v_tenant_id IS NULL THEN
        SELECT id INTO v_tenant_id
        FROM public.tenants
        WHERE name = p_tenant_name
        LIMIT 1;
    END IF;
    
    RETURN v_tenant_id;
END;
$$;


ALTER FUNCTION "inventory"."create_test_tenant"("p_tenant_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."emit_abc_classification_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Emit event when classification changes
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.classification != NEW.classification) THEN
    INSERT INTO inventory.events_outbox (
      event_id,
      tenant_id,
      event_type,
      aggregate_type,
      aggregate_id,
      payload,
      status
    ) VALUES (
      gen_random_uuid(),
      NEW.tenant_id,
      CASE TG_OP
        WHEN 'INSERT' THEN 'abc_classification_created'
        WHEN 'UPDATE' THEN 'abc_classification_changed'
      END,
      'catalog_item',
      NEW.catalog_item_id,
      jsonb_build_object(
        'catalog_item_id', NEW.catalog_item_id,
        'classification', NEW.classification,
        'old_classification', CASE WHEN TG_OP = 'UPDATE' THEN OLD.classification ELSE NULL END,
        'annual_usage_value', NEW.annual_usage_value,
        'cumulative_value_pct', NEW.cumulative_value_pct,
        'classification_method', NEW.classification_method,
        'analysis_period', jsonb_build_object(
          'start', NEW.analysis_start_date,
          'end', NEW.analysis_end_date
        )
      ),
      'pending'
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_abc_classification_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_abc_classification_event"() IS 'Emits ABC classification events to events_outbox when items are classified or reclassified';



CREATE OR REPLACE FUNCTION "inventory"."emit_asset_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
    v_changes JSONB;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_event_name := 'asset.created';
        v_payload := jsonb_build_object(
            'asset_id', NEW.id,
            'asset_tag', NEW.asset_tag,
            'serial_number', NEW.serial_number,
            'vin', NEW.vin,
            'catalog_item_id', NEW.catalog_item_id,
            'status', NEW.status,
            'home_location_id', NEW.home_location_id,
            'tenant_id', NEW.tenant_id,
            'created_at', NEW.created_at
        );
    ELSIF TG_OP = 'UPDATE' THEN
        -- Check for retirement
        IF NEW.status = 'retired' AND OLD.status != 'retired' THEN
            v_event_name := 'asset.retired';
            v_payload := jsonb_build_object(
                'asset_id', NEW.id,
                'asset_tag', NEW.asset_tag,
                'tenant_id', NEW.tenant_id,
                'retired_at', NEW.updated_at
            );
        ELSE
            -- Regular update
            v_event_name := 'asset.updated';
            v_changes := jsonb_build_object();
            
            IF OLD.status != NEW.status THEN
                v_changes := v_changes || jsonb_build_object('status', jsonb_build_object('old', OLD.status, 'new', NEW.status));
            END IF;
            IF OLD.home_location_id IS DISTINCT FROM NEW.home_location_id THEN
                v_changes := v_changes || jsonb_build_object('home_location_id', jsonb_build_object('old', OLD.home_location_id, 'new', NEW.home_location_id));
            END IF;
            
            v_payload := jsonb_build_object(
                'asset_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'changes', v_changes,
                'updated_at', NEW.updated_at
            );
        END IF;
    END IF;
    
    PERFORM public.emit_event(
        v_event_name,
        v_payload,
        NEW.tenant_id
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_asset_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."emit_catalog_item_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
    v_changes JSONB;
BEGIN
    -- Determine event type
    IF TG_OP = 'INSERT' THEN
        v_event_name := 'inventory.item.created';
        v_payload := jsonb_build_object(
            'item_id', NEW.id,
            'sku', NEW.sku,
            'name', NEW.name,
            'category_id', NEW.category_id,
            'tracking_mode', NEW.tracking_mode,
            'uom', NEW.uom,
            'tenant_id', NEW.tenant_id,
            'created_at', NEW.created_at
        );
    ELSIF TG_OP = 'UPDATE' THEN
        -- Check for deactivation
        IF OLD.active = TRUE AND NEW.active = FALSE THEN
            v_event_name := 'catalog_item.deactivated';
            v_payload := jsonb_build_object(
                'item_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'deactivated_at', NEW.updated_at
            );
        -- Check for reactivation
        ELSIF OLD.active = FALSE AND NEW.active = TRUE THEN
            v_event_name := 'catalog_item.reactivated';
            v_payload := jsonb_build_object(
                'item_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'reactivated_at', NEW.updated_at
            );
        ELSE
            -- Regular update
            v_event_name := 'catalog_item.updated';
            v_changes := jsonb_build_object();
            
            IF OLD.name != NEW.name THEN
                v_changes := v_changes || jsonb_build_object('name', jsonb_build_object('old', OLD.name, 'new', NEW.name));
            END IF;
            IF OLD.sku != NEW.sku THEN
                v_changes := v_changes || jsonb_build_object('sku', jsonb_build_object('old', OLD.sku, 'new', NEW.sku));
            END IF;
            IF OLD.uom IS DISTINCT FROM NEW.uom THEN
                v_changes := v_changes || jsonb_build_object('uom', jsonb_build_object('old', OLD.uom, 'new', NEW.uom));
            END IF;
            IF OLD.category_id IS DISTINCT FROM NEW.category_id THEN
                v_changes := v_changes || jsonb_build_object('category_id', jsonb_build_object('old', OLD.category_id, 'new', NEW.category_id));
            END IF;
            
            v_payload := jsonb_build_object(
                'item_id', NEW.id,
                'tenant_id', NEW.tenant_id,
                'changes', v_changes,
                'updated_at', NEW.updated_at
            );
        END IF;
    END IF;
    
    -- Emit event
    PERFORM public.emit_event(
        v_event_name,
        v_payload,
        NEW.tenant_id
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_catalog_item_event"() OWNER TO "postgres";


