CREATE OR REPLACE FUNCTION "inventory"."emit_cycle_count_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Emit event when cycle count is created
    IF TG_OP = 'INSERT' THEN
        PERFORM inventory.publish_event(
            p_tenant_id := NEW.tenant_id,
            p_scope := 'tenant',
            p_event_type := 'inventory.cycle_count.created',
            p_aggregate_type := 'cycle_count',
            p_aggregate_id := NEW.id,
            p_payload := to_jsonb(NEW),
            p_metadata := jsonb_build_object(
                'location_id', NEW.location_id,
                'count_date', NEW.count_date
            )
        );
    END IF;
    
    -- Note: Cycle counts table structure needs verification
    -- If status column exists, add status change event here
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_cycle_count_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_cycle_count_event"() IS 'Emits events for cycle count creation (status change handling TBD based on schema)';



