CREATE OR REPLACE FUNCTION "inventory"."emit_reorder_alert_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Only emit events for new alerts or status changes
  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status != NEW.status) THEN
    INSERT INTO inventory.events_outbox (
      event_id,
      tenant_id,
      event_type,
      aggregate_type,
      aggregate_id,
      payload,
      status
    ) VALUES (
      gen_random_uuid(),
      NEW.tenant_id,
      CASE TG_OP
        WHEN 'INSERT' THEN 'reorder_alert_created'
        WHEN 'UPDATE' THEN 'reorder_alert_status_changed'
      END,
      'reorder_alert',
      NEW.id,
      jsonb_build_object(
        'alert_id', NEW.id,
        'catalog_item_id', NEW.catalog_item_id,
        'location_id', NEW.location_id,
        'alert_type', NEW.alert_type,
        'priority', NEW.priority,
        'status', NEW.status,
        'current_qty', NEW.current_qty,
        'reorder_point', NEW.reorder_point,
        'suggested_order_qty', NEW.suggested_order_qty,
        'old_status', CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END
      ),
      'pending'
    );
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_reorder_alert_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_reorder_alert_event"() IS 'Emits reorder alert events to events_outbox when alerts are created or status changes';



CREATE OR REPLACE FUNCTION "inventory"."emit_stock_movement_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
BEGIN
    -- Determine specific event type based on movement type
    CASE NEW.movement_type
        WHEN 'received' THEN
            v_event_name := 'stock.replenished';
            v_payload := jsonb_build_object(
                'movement_id', NEW.id,
                'item_id', NEW.catalog_item_id,
                'location_id', NEW.location_id,
                'quantity_delta', NEW.quantity_delta,
                'source_ref_type', NEW.source_ref_type,
                'source_ref_id', NEW.source_ref_id,
                'tenant_id', NEW.tenant_id,
                'occurred_at', NEW.occurred_at
            );
        WHEN 'issued' THEN
            v_event_name := 'stock.issued';
            v_payload := jsonb_build_object(
                'movement_id', NEW.id,
                'item_id', NEW.catalog_item_id,
                'location_id', NEW.location_id,
                'quantity_delta', NEW.quantity_delta,
                'tenant_id', NEW.tenant_id,
                'occurred_at', NEW.occurred_at
            );
        WHEN 'returned' THEN
            v_event_name := 'stock.returned';
            v_payload := jsonb_build_object(
                'movement_id', NEW.id,
                'item_id', NEW.catalog_item_id,
                'location_id', NEW.location_id,
                'quantity_delta', NEW.quantity_delta,
                'tenant_id', NEW.tenant_id,
                'occurred_at', NEW.occurred_at
            );
        WHEN 'transferred_in', 'transferred_out' THEN
            v_event_name := 'stock.transferred';
            v_payload := jsonb_build_object(
                'movement_id', NEW.id,
                'item_id', NEW.catalog_item_id,
                'location_id', NEW.location_id,
                'quantity_delta', NEW.quantity_delta,
                'correlation_id', NEW.correlation_id,
                'tenant_id', NEW.tenant_id,
                'occurred_at', NEW.occurred_at
            );
        ELSE
            -- Default to generic stock.adjusted event
            v_event_name := 'stock.adjusted';
            v_payload := jsonb_build_object(
                'movement_id', NEW.id,
                'item_id', NEW.catalog_item_id,
                'location_id', NEW.location_id,
                'quantity_delta', NEW.quantity_delta,
                'movement_type', NEW.movement_type,
                'tenant_id', NEW.tenant_id,
                'occurred_at', NEW.occurred_at
            );
    END CASE;
    
    -- Emit the event
    PERFORM public.emit_event(
        v_event_name,
        v_payload,
        NEW.tenant_id
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_stock_movement_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."emit_stock_movement_event"() IS 'Emits events for stock movements (FIXED: uses catalog_item_id)';



CREATE OR REPLACE FUNCTION "inventory"."emit_stock_threshold_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_par_level RECORD;
    v_payload JSONB;
BEGIN
    -- Only check on UPDATE when quantity decreases
    IF TG_OP = 'UPDATE' AND NEW.qty_on_hand < OLD.qty_on_hand THEN
        -- Check if there's a par level defined
        SELECT * INTO v_par_level
        FROM inventory.item_location_par_levels
        WHERE catalog_item_id = NEW.catalog_item_id
          AND location_id = NEW.location_id
          AND tenant_id = NEW.tenant_id;
        
        IF FOUND THEN
            -- Check if we just crossed the reorder point
            IF OLD.qty_on_hand >= v_par_level.reorder_point AND NEW.qty_on_hand < v_par_level.reorder_point THEN
                v_payload := jsonb_build_object(
                    'item_id', NEW.catalog_item_id,
                    'location_id', NEW.location_id,
                    'current_qty', NEW.qty_on_hand,
                    'reorder_point', v_par_level.reorder_point,
                    'reorder_qty', v_par_level.reorder_qty,
                    'tenant_id', NEW.tenant_id,
                    'detected_at', NOW()
                );
                
                PERFORM public.emit_event(
                    'stock.low_threshold_reached',
                    v_payload,
                    NEW.tenant_id
                );
            END IF;
            
            -- Check if we just went out of stock
            IF OLD.qty_on_hand > 0 AND NEW.qty_on_hand <= 0 THEN
                v_payload := jsonb_build_object(
                    'item_id', NEW.catalog_item_id,
                    'location_id', NEW.location_id,
                    'previous_qty', OLD.qty_on_hand,
                    'tenant_id', NEW.tenant_id,
                    'occurred_at', NOW()
                );
                
                PERFORM public.emit_event(
                    'stock.out_of_stock',
                    v_payload,
                    NEW.tenant_id
                );
            END IF;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."emit_stock_threshold_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."expire_old_reservations"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE inventory.reservations
    SET 
        status = 'expired',
        updated_at = NOW()
    WHERE status = 'active'
    AND expiration_date IS NOT NULL
    AND expiration_date < CURRENT_DATE
    AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id);
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    
    RETURN v_count;
END;
$$;


ALTER FUNCTION "inventory"."expire_old_reservations"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."expire_old_reservations"("p_tenant_id" "uuid") IS 'Auto-expires reservations past their expiration date (run via cron)';



CREATE OR REPLACE FUNCTION "inventory"."generate_reorder_alerts"() RETURNS TABLE("alerts_created" integer, "alerts_updated" integer, "alerts_auto_dismissed" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_alerts_created INTEGER := 0;
  v_alerts_updated INTEGER := 0;
  v_alerts_dismissed INTEGER := 0;
  v_item RECORD;
  v_existing_alert_id UUID;
BEGIN
  -- Loop through items needing reorder
  FOR v_item IN 
    SELECT * FROM inventory.v_items_needing_reorder
  LOOP
    -- Check if alert already exists for this item/location
    SELECT id INTO v_existing_alert_id
    FROM inventory.reorder_alerts
    WHERE tenant_id = v_item.tenant_id
      AND catalog_item_id = v_item.catalog_item_id
      AND location_id = v_item.location_id
      AND status IN ('open', 'acknowledged')
    LIMIT 1;

    IF v_existing_alert_id IS NOT NULL THEN
      -- Update existing alert with current quantities
      UPDATE inventory.reorder_alerts
      SET
        alert_type = v_item.alert_type,
        current_qty = v_item.qty_available,
        priority = v_item.alert_priority,
        suggested_order_qty = v_item.suggested_order_qty,
        updated_at = now()
      WHERE id = v_existing_alert_id;
      
      v_alerts_updated := v_alerts_updated + 1;
    ELSE
      -- Create new alert
      INSERT INTO inventory.reorder_alerts (
        tenant_id,
        catalog_item_id,
        location_id,
        alert_type,
        current_qty,
        reorder_point,
        min_stock_level,
        target_level,
        suggested_order_qty,
        priority,
        status
      ) VALUES (
        v_item.tenant_id,
        v_item.catalog_item_id,
        v_item.location_id,
        v_item.alert_type,
        v_item.qty_available,
        v_item.reorder_point,
        v_item.min_stock_level,
        v_item.target_level,
        v_item.suggested_order_qty,
        v_item.alert_priority,
        'open'
      );
      
      v_alerts_created := v_alerts_created + 1;
    END IF;
  END LOOP;

  -- Auto-dismiss alerts for items that are now above reorder point
  WITH dismissed AS (
    UPDATE inventory.reorder_alerts ra
    SET 
      status = 'dismissed',
      dismissed_reason = 'Stock level restored above reorder point',
      dismissed_at = now(),
      updated_at = now()
    WHERE ra.status IN ('open', 'acknowledged')
      AND NOT EXISTS (
        SELECT 1 
        FROM inventory.v_items_needing_reorder inr
        WHERE inr.tenant_id = ra.tenant_id
          AND inr.catalog_item_id = ra.catalog_item_id
          AND inr.location_id = ra.location_id
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_alerts_dismissed FROM dismissed;

  RETURN QUERY SELECT v_alerts_created, v_alerts_updated, v_alerts_dismissed;
END;
$$;


ALTER FUNCTION "inventory"."generate_reorder_alerts"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."generate_reorder_alerts"() IS 'Scans stock levels and generates/updates reorder alerts. Auto-dismisses resolved alerts. Run via cron every hour.';



CREATE OR REPLACE FUNCTION "inventory"."get_failed_events"("p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "tenant_id" "uuid", "event_type" "text", "aggregate_type" "text", "aggregate_id" "uuid", "retry_count" integer, "last_error" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.id,
        e.tenant_id,
        e.event_type,
        e.aggregate_type,
        e.aggregate_id,
        e.retry_count,
        e.last_error,
        e.created_at
    FROM inventory.events_outbox e
    WHERE e.status = 'failed'
    AND (p_tenant_id IS NULL OR e.tenant_id = p_tenant_id)
    ORDER BY e.created_at DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "inventory"."get_failed_events"("p_tenant_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."get_failed_events"("p_tenant_id" "uuid", "p_limit" integer) IS 'Returns failed events for monitoring and debugging. Can be filtered by tenant_id.';



CREATE OR REPLACE FUNCTION "inventory"."get_outbox_stats"("p_tenant_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("tenant_id" "uuid", "total_events" bigint, "pending_events" bigint, "published_events" bigint, "failed_events" bigint, "avg_processing_time_seconds" numeric, "oldest_pending_age_seconds" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        e.tenant_id,
        COUNT(*)::BIGINT AS total_events,
        COUNT(*) FILTER (WHERE e.status = 'pending')::BIGINT AS pending_events,
        COUNT(*) FILTER (WHERE e.status = 'published')::BIGINT AS published_events,
        COUNT(*) FILTER (WHERE e.status = 'failed')::BIGINT AS failed_events,
        AVG(EXTRACT(EPOCH FROM (e.published_at - e.created_at))) FILTER (WHERE e.published_at IS NOT NULL) AS avg_processing_time_seconds,
        EXTRACT(EPOCH FROM (NOW() - MIN(e.created_at) FILTER (WHERE e.status = 'pending'))) AS oldest_pending_age_seconds
    FROM inventory.events_outbox e
    WHERE p_tenant_id IS NULL OR e.tenant_id = p_tenant_id
    GROUP BY e.tenant_id;
END;
$$;


ALTER FUNCTION "inventory"."get_outbox_stats"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."get_outbox_stats"("p_tenant_id" "uuid") IS 'Returns statistics about outbox events for monitoring dashboards. Can be filtered by tenant_id.';



CREATE OR REPLACE FUNCTION "inventory"."get_substitutes"("p_item_id" "uuid", "p_tenant_id" "uuid") RETURNS TABLE("substitute_item_id" "uuid", "sku" "text", "name" "text", "priority" integer, "conversion_factor" numeric, "qty_available" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        s.substitute_item_id,
        ci.sku,
        ci.name,
        s.priority,
        s.conversion_factor,
        COALESCE(SUM(sb.qty_available), 0) as qty_available
    FROM inventory.item_substitutions s
    JOIN inventory.catalog_items ci ON ci.id = s.substitute_item_id
    LEFT JOIN inventory.stock_balances sb ON sb.catalog_item_id = s.substitute_item_id 
        AND sb.tenant_id = p_tenant_id
    WHERE s.item_id = p_item_id
    AND s.tenant_id = p_tenant_id
    AND s.active = TRUE
    GROUP BY s.substitute_item_id, ci.sku, ci.name, s.priority, s.conversion_factor
    ORDER BY s.priority ASC, qty_available DESC;
END;
$$;


ALTER FUNCTION "inventory"."get_substitutes"("p_item_id" "uuid", "p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."get_substitutes"("p_item_id" "uuid", "p_tenant_id" "uuid") IS 'Returns active substitutes for an item, ordered by priority and availability';



CREATE OR REPLACE FUNCTION "inventory"."insert_asset_event"("p_tenant_id" "uuid", "p_event_type" "text", "p_occurred_at" timestamp with time zone, "p_asset_id" "uuid", "p_actor_user_id" "uuid", "p_source_system" "text", "p_last_event_id" "text", "p_payload" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_id UUID;
BEGIN
    INSERT INTO inventory.asset_events (
        tenant_id,
        event_type,
        occurred_at,
        asset_id,
        actor_user_id,
        source_system,
        last_event_id,
        payload
    ) VALUES (
        p_tenant_id,
        p_event_type,
        p_occurred_at,
        p_asset_id,
        p_actor_user_id,
        p_source_system,
        p_last_event_id,
        p_payload
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_event_id;
    
    -- If conflict occurred, get existing event id
    IF v_event_id IS NULL THEN
        SELECT id INTO v_event_id
        FROM inventory.asset_events
        WHERE tenant_id = p_tenant_id AND last_event_id = p_last_event_id;
    END IF;
    
    RETURN v_event_id;
END;
$$;


