CREATE OR REPLACE FUNCTION "inventory"."is_hazardous"("p_catalog_item_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_hazard_flags JSONB;
    v_key TEXT;
BEGIN
    SELECT hazard_flags INTO v_hazard_flags
    FROM inventory.catalog_items
    WHERE id = p_catalog_item_id;
    
    IF v_hazard_flags IS NULL OR v_hazard_flags = '{}' THEN
        RETURN FALSE;
    END IF;
    
    -- Check if any hazard flag is true
    FOR v_key IN SELECT jsonb_object_keys(v_hazard_flags)
    LOOP
        IF (v_hazard_flags->>v_key)::BOOLEAN = TRUE THEN
            RETURN TRUE;
        END IF;
    END LOOP;
    
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "inventory"."is_hazardous"("p_catalog_item_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."is_hazardous"("p_catalog_item_id" "uuid") IS 'Returns true if catalog item has any hazard flags set to true';



CREATE OR REPLACE FUNCTION "inventory"."maintain_stock_balances"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Upsert stock_balances for this item/location combination
    INSERT INTO inventory.stock_balances (
        tenant_id,
        catalog_item_id,
        location_id,
        qty_on_hand
    ) VALUES (
        NEW.tenant_id,
        NEW.catalog_item_id,
        NEW.location_id,
        NEW.quantity_delta
    )
    ON CONFLICT (tenant_id, catalog_item_id, location_id)
    DO UPDATE SET
        qty_on_hand = inventory.stock_balances.qty_on_hand + NEW.quantity_delta,
        updated_at = NOW();
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."maintain_stock_balances"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."maintain_stock_balances"() IS 'Automatically maintains stock_balances read model when stock_movements are inserted';



CREATE OR REPLACE FUNCTION "inventory"."maintain_stock_reserved"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'active' THEN
        -- Increase reserved quantity
        UPDATE inventory.stock_balances
        SET qty_reserved = qty_reserved + NEW.qty,
            updated_at = NOW()
        WHERE tenant_id = NEW.tenant_id
          AND catalog_item_id = NEW.catalog_item_id
          AND location_id = NEW.location_id;
          
        -- Create stock_balances record if it doesn't exist
        INSERT INTO inventory.stock_balances (
            tenant_id,
            catalog_item_id,
            location_id,
            qty_on_hand,
            qty_reserved
        ) VALUES (
            NEW.tenant_id,
            NEW.catalog_item_id,
            NEW.location_id,
            0,
            NEW.qty
        )
        ON CONFLICT (tenant_id, catalog_item_id, location_id) DO NOTHING;
        
    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.status = 'active' AND NEW.status IN ('fulfilled', 'cancelled') THEN
            -- Decrease reserved quantity
            UPDATE inventory.stock_balances
            SET qty_reserved = GREATEST(0, qty_reserved - OLD.qty),
                updated_at = NOW()
            WHERE tenant_id = OLD.tenant_id
              AND catalog_item_id = OLD.catalog_item_id
              AND location_id = OLD.location_id;
        END IF;
        
    ELSIF TG_OP = 'DELETE' AND OLD.status = 'active' THEN
        -- Decrease reserved quantity on delete
        UPDATE inventory.stock_balances
        SET qty_reserved = GREATEST(0, qty_reserved - OLD.qty),
            updated_at = NOW()
        WHERE tenant_id = OLD.tenant_id
          AND catalog_item_id = OLD.catalog_item_id
          AND location_id = OLD.location_id;
    END IF;
    
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "inventory"."maintain_stock_reserved"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."maintain_stock_reserved"() IS 'Automatically maintains stock_balances.qty_reserved when reservations change';



CREATE OR REPLACE FUNCTION "inventory"."move_to_dead_letter"("p_event_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event RECORD;
BEGIN
    -- Fetch event from outbox
    SELECT * INTO v_event FROM inventory.events_outbox WHERE id = p_event_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Event % not found', p_event_id;
    END IF;

    -- Insert into DLQ
    INSERT INTO public.events_dead_letter (
        original_event_id,
        event_type,
        tenant_id,
        payload,
        created_at,
        final_error,
        total_attempts,
        original_metadata,
        original_scope,
        original_aggregate_type,
        original_aggregate_id,
        original_actor_user_id
    ) VALUES (
        v_event.id,
        v_event.event_type,
        v_event.tenant_id,
        v_event.payload,
        v_event.created_at,
        v_event.last_error,
        v_event.retry_count,
        v_event.metadata,
        v_event.scope,
        v_event.aggregate_type,
        v_event.aggregate_id,
        v_event.actor_user_id
    );

    -- Update status to 'dead' in outbox
    UPDATE inventory.events_outbox 
    SET status = 'dead', 
        locked_at = NULL, 
        locked_by = NULL
    WHERE id = p_event_id;

    RAISE NOTICE 'Event % moved to dead letter queue', p_event_id;
END;
$$;


ALTER FUNCTION "inventory"."move_to_dead_letter"("p_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."move_to_dead_letter"("p_event_id" "uuid") IS 'Moves failed event to dead letter queue after max retries';



CREATE OR REPLACE FUNCTION "inventory"."prevent_event_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Allow status, lock, and error field updates
    IF OLD.event_type IS DISTINCT FROM NEW.event_type THEN
        RAISE EXCEPTION 'event_type cannot be modified after insert (event_id: %)', OLD.id;
    END IF;

    IF OLD.payload IS DISTINCT FROM NEW.payload THEN
        RAISE EXCEPTION 'payload cannot be modified after insert (event_id: %)', OLD.id;
    END IF;

    IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
        RAISE EXCEPTION 'tenant_id cannot be modified after insert (event_id: %)', OLD.id;
    END IF;

    -- Allow all other updates (status, locked_at, retry_count, etc.)
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."prevent_event_mutation"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."prevent_event_mutation"() IS 'Ensures event_type, payload, and tenant_id are immutable after insert';



CREATE OR REPLACE FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_id UUID;
BEGIN
    -- Insert into outbox
    INSERT INTO inventory.events_outbox (
        tenant_id,
        scope,
        event_type,
        aggregate_type,
        aggregate_id,
        payload,
        metadata,
        status,
        retry_count
    ) VALUES (
        p_tenant_id,
        p_scope,
        p_event_type,
        p_aggregate_type,
        p_aggregate_id,
        p_payload,
        p_metadata,
        'pending',
        0
    ) RETURNING id INTO v_event_id;
    
    RETURN v_event_id;
END;
$$;


ALTER FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_type" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_metadata" "jsonb") IS 'Publishes an event to the outbox for async processing by the events poller';



CREATE OR REPLACE FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_name" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_event_version" integer DEFAULT 1, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_id UUID;
BEGIN
    -- Soft validation: log warning if event not in catalog
    PERFORM public.validate_event_in_catalog(p_event_name, p_event_version);
    
    INSERT INTO inventory.events_outbox (
        tenant_id,
        scope,
        event_type,  -- Keep for backwards compatibility
        event_name,
        event_version,
        aggregate_type,
        aggregate_id,
        payload,
        metadata,
        status
    ) VALUES (
        p_tenant_id,
        p_scope,
        p_event_name,  -- Same as event_name
        p_event_name,
        p_event_version,
        p_aggregate_type,
        p_aggregate_id,
        p_payload,
        p_metadata,
        'pending'
    ) RETURNING id INTO v_event_id;
    
    RETURN v_event_id;
END;
$$;


ALTER FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_name" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_event_version" integer, "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."publish_event"("p_tenant_id" "uuid", "p_scope" "text", "p_event_name" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_payload" "jsonb", "p_event_version" integer, "p_metadata" "jsonb") IS 'Publish event to outbox with catalog validation';



CREATE OR REPLACE FUNCTION "inventory"."refresh_dashboard_views"() RETURNS TABLE("view_name" "text", "row_count" bigint, "refresh_time_ms" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_start TIMESTAMPTZ;
    v_count BIGINT;
BEGIN
    -- Refresh inventory summary
    v_start := clock_timestamp();
    REFRESH MATERIALIZED VIEW CONCURRENTLY inventory.mv_inventory_summary;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN QUERY SELECT 
        'mv_inventory_summary'::TEXT,
        v_count,
        EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_start));
    
    -- Refresh low stock summary
    v_start := clock_timestamp();
    REFRESH MATERIALIZED VIEW CONCURRENTLY inventory.mv_low_stock_summary;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN QUERY SELECT 
        'mv_low_stock_summary'::TEXT,
        v_count,
        EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_start));
    
    -- Refresh asset utilization
    v_start := clock_timestamp();
    REFRESH MATERIALIZED VIEW CONCURRENTLY inventory.mv_asset_utilization;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN QUERY SELECT 
        'mv_asset_utilization'::TEXT,
        v_count,
        EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_start));
END;
$$;


ALTER FUNCTION "inventory"."refresh_dashboard_views"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."refresh_dashboard_views"() IS 'Refreshes all dashboard materialized views and reports timing';



CREATE OR REPLACE FUNCTION "inventory"."retry_failed_event"("p_event_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    UPDATE inventory.events_outbox
    SET 
        status = 'pending',
        retry_count = 0,
        last_error = NULL
    WHERE id = p_event_id
    AND status = 'failed';
    
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    
    RETURN v_updated > 0;
END;
$$;


ALTER FUNCTION "inventory"."retry_failed_event"("p_event_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."retry_failed_event"("p_event_id" "uuid") IS 'Manually retries a failed event by resetting its status to pending and clearing retry count.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_acknowledge_alert"("p_alert_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
  v_user_id UUID;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  v_tenant_id := current_tenant_id();
  
  -- Update alert
  UPDATE inventory.reorder_alerts
  SET
    status = 'acknowledged',
    acknowledged_by = v_user_id,
    acknowledged_at = now(),
    updated_at = now()
  WHERE id = p_alert_id
    AND tenant_id = v_tenant_id
    AND status = 'open';
    
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert not found or already acknowledged';
  END IF;
END;
$$;


ALTER FUNCTION "inventory"."rpc_acknowledge_alert"("p_alert_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_adjust_inventory"("p_location_id" "uuid", "p_catalog_item_id" "uuid", "p_new_qty" numeric, "p_reason" "text", "p_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_current_qty NUMERIC;
  v_delta NUMERIC;
  v_event_id TEXT;
  v_result JSONB;
BEGIN
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  IF p_reason IS NULL OR trim(p_reason) = '' THEN
    RAISE EXCEPTION 'Reason required for inventory adjustment';
  END IF;
  
  -- Get current quantity
  SELECT COALESCE(qty_on_hand, 0)
  INTO v_current_qty
  FROM inventory.stock_balances
  WHERE tenant_id = v_tenant_id
    AND catalog_item_id = p_catalog_item_id
    AND location_id = p_location_id;
  
  IF v_current_qty IS NULL THEN
    v_current_qty := 0;
  END IF;
  
  v_delta := p_new_qty - v_current_qty;
  
  IF v_delta = 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'No adjustment needed (quantity unchanged)',
      'current_qty', v_current_qty,
      'new_qty', p_new_qty,
      'delta', 0
    );
  END IF;
  
  v_event_id := 'adjust-' || gen_random_uuid()::TEXT || '-' || extract(epoch from now())::TEXT;
  
  -- Insert inventory event
  INSERT INTO inventory.inventory_events (
    tenant_id,
    catalog_item_id,
    location_id,
    event_type,
    quantity_delta,
    payload,
    occurred_at,
    actor_user_id,
    last_event_id
  ) VALUES (
    v_tenant_id,
    p_catalog_item_id,
    p_location_id,
    'adjust',
    v_delta,
    jsonb_build_object(
      'reason', p_reason,
      'old_qty', v_current_qty,
      'new_qty', p_new_qty,
      'notes', p_notes
    ),
    NOW(),
    (auth.jwt() ->> 'user_id')::UUID,
    v_event_id
  );
  
  -- Insert stock movement
  INSERT INTO inventory.stock_movements (
    tenant_id,
    catalog_item_id,
    location_id,
    quantity_delta,
    movement_type,
    reason,
    notes,
    occurred_at,
    created_by_user_id,
    last_event_id
  ) VALUES (
    v_tenant_id,
    p_catalog_item_id,
    p_location_id,
    v_delta,
    'adjusted',
    p_reason,
    p_notes,
    NOW(),
    (auth.jwt() ->> 'user_id')::UUID,
    v_event_id
  );
  
  -- Update stock balances
  INSERT INTO inventory.stock_balances (
    tenant_id,
    catalog_item_id,
    location_id,
    qty_on_hand,
    qty_reserved,
    qty_available,
    last_event_id
  ) VALUES (
    v_tenant_id,
    p_catalog_item_id,
    p_location_id,
    p_new_qty,
    0,
    p_new_qty,
    v_event_id
  )
  ON CONFLICT (tenant_id, catalog_item_id, location_id)
  DO UPDATE SET
    qty_on_hand = EXCLUDED.qty_on_hand,
    qty_available = stock_balances.qty_available + (EXCLUDED.qty_on_hand - stock_balances.qty_on_hand),
    last_event_id = EXCLUDED.last_event_id,
    updated_at = NOW();
  
  v_result := jsonb_build_object(
    'success', true,
    'catalog_item_id', p_catalog_item_id,
    'location_id', p_location_id,
    'old_qty', v_current_qty,
    'new_qty', p_new_qty,
    'delta', v_delta,
    'reason', p_reason
  );
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "inventory"."rpc_adjust_inventory"("p_location_id" "uuid", "p_catalog_item_id" "uuid", "p_new_qty" numeric, "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_adjust_inventory"("p_location_id" "uuid", "p_catalog_item_id" "uuid", "p_new_qty" numeric, "p_reason" "text", "p_notes" "text") IS 'Frontend RPC: Adjust inventory to a new quantity.
Requires reason (count_variance, damage, theft, expiration, other).
Returns: {success, old_qty, new_qty, delta, reason}';



CREATE OR REPLACE FUNCTION "inventory"."rpc_calculate_abc_classification"("p_start_date" "date" DEFAULT (CURRENT_DATE - '365 days'::interval), "p_end_date" "date" DEFAULT CURRENT_DATE, "p_method" "text" DEFAULT 'value'::"text") RETURNS TABLE("items_classified" integer, "class_a_count" integer, "class_b_count" integer, "class_c_count" integer, "class_d_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
  v_total_value NUMERIC(18,2);
  v_items_classified INTEGER := 0;
  v_class_a INTEGER := 0;
  v_class_b INTEGER := 0;
  v_class_c INTEGER := 0;
  v_class_d INTEGER := 0;
BEGIN
  v_tenant_id := current_tenant_id();
  
  -- Calculate usage metrics for each item
  WITH item_usage AS (
    SELECT
      sm.catalog_item_id,
      SUM(ABS(sm.quantity_delta)) FILTER (WHERE sm.movement_type IN ('issued', 'consumed')) AS total_usage_qty,
      AVG(pol.unit_cost) AS avg_unit_cost
    FROM inventory.stock_movements sm
    LEFT JOIN inventory.receipt_lines rl ON rl.receipt_id::TEXT = sm.source_ref_id::TEXT AND sm.source_ref_type = 'receipt'
    LEFT JOIN inventory.purchase_order_lines pol ON pol.id = rl.po_line_id
    WHERE sm.tenant_id = v_tenant_id
      AND sm.created_at BETWEEN p_start_date AND p_end_date
      AND sm.movement_state = 'confirmed'
    GROUP BY sm.catalog_item_id
  ),
  item_metrics AS (
    SELECT
      iu.catalog_item_id,
      COALESCE(iu.total_usage_qty, 0) AS annual_usage_qty,
      COALESCE(iu.total_usage_qty, 0) * COALESCE(iu.avg_unit_cost, 0) AS annual_usage_value
    FROM item_usage iu
  ),
  ranked_items AS (
    SELECT
      catalog_item_id,
      annual_usage_qty,
      annual_usage_value,
      ROW_NUMBER() OVER (ORDER BY annual_usage_value DESC) AS value_rank,
      ROW_NUMBER() OVER (ORDER BY annual_usage_qty DESC) AS usage_rank,
      SUM(annual_usage_value) OVER (ORDER BY annual_usage_value DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_value,
      SUM(annual_usage_value) OVER () AS total_value
    FROM item_metrics
    WHERE annual_usage_value > 0
  ),
  classified_items AS (
    SELECT
      catalog_item_id,
      annual_usage_qty,
      annual_usage_value,
      cumulative_value / NULLIF(total_value, 0) AS cumulative_value_pct,
      value_rank,
      usage_rank,
      CASE
        WHEN p_method = 'value' THEN
          CASE
            WHEN cumulative_value / NULLIF(total_value, 0) <= 0.80 THEN 'A'
            WHEN cumulative_value / NULLIF(total_value, 0) <= 0.95 THEN 'B'
            ELSE 'C'
          END
        WHEN p_method = 'usage' THEN
          CASE
            WHEN usage_rank <= (SELECT COUNT(*) * 0.20 FROM ranked_items) THEN 'A'
            WHEN usage_rank <= (SELECT COUNT(*) * 0.50 FROM ranked_items) THEN 'B'
            ELSE 'C'
          END
        ELSE -- hybrid
          CASE
            WHEN (cumulative_value / NULLIF(total_value, 0) <= 0.70 AND usage_rank <= (SELECT COUNT(*) * 0.30 FROM ranked_items)) THEN 'A'
            WHEN (cumulative_value / NULLIF(total_value, 0) <= 0.90 OR usage_rank <= (SELECT COUNT(*) * 0.60 FROM ranked_items)) THEN 'B'
            ELSE 'C'
          END
      END AS classification
    FROM ranked_items
  )
  -- Insert or update classifications
  INSERT INTO inventory.abc_classification (
    tenant_id,
    catalog_item_id,
    classification,
    annual_usage_qty,
    annual_usage_value,
    cumulative_value_pct,
    classification_method,
    value_rank,
    usage_rank,
    analysis_start_date,
    analysis_end_date
  )
  SELECT
    v_tenant_id,
    ci.catalog_item_id,
    ci.classification,
    ci.annual_usage_qty,
    ci.annual_usage_value,
    ci.cumulative_value_pct,
    p_method,
    ci.value_rank,
    ci.usage_rank,
    p_start_date,
    p_end_date
  FROM classified_items ci
  ON CONFLICT (tenant_id, catalog_item_id, analysis_end_date)
  DO UPDATE SET
    classification = EXCLUDED.classification,
    annual_usage_qty = EXCLUDED.annual_usage_qty,
    annual_usage_value = EXCLUDED.annual_usage_value,
    cumulative_value_pct = EXCLUDED.cumulative_value_pct,
    classification_method = EXCLUDED.classification_method,
    value_rank = EXCLUDED.value_rank,
    usage_rank = EXCLUDED.usage_rank,
    updated_at = now();
  
  -- Get classification counts
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE classification = 'A'),
    COUNT(*) FILTER (WHERE classification = 'B'),
    COUNT(*) FILTER (WHERE classification = 'C'),
    COUNT(*) FILTER (WHERE classification = 'D')
  INTO v_items_classified, v_class_a, v_class_b, v_class_c, v_class_d
  FROM inventory.abc_classification
  WHERE tenant_id = v_tenant_id
    AND analysis_end_date = p_end_date;
  
  RETURN QUERY SELECT v_items_classified, v_class_a, v_class_b, v_class_c, v_class_d;
END;
$$;


ALTER FUNCTION "inventory"."rpc_calculate_abc_classification"("p_start_date" "date", "p_end_date" "date", "p_method" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_calculate_abc_classification"("p_start_date" "date", "p_end_date" "date", "p_method" "text") IS 'Calculates ABC classification for all items based on usage/value. A = top 80% value, B = next 15%, C = remaining 5%';



CREATE OR REPLACE FUNCTION "inventory"."rpc_dismiss_alert"("p_alert_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
  v_user_id UUID;
BEGIN
  -- Get current user
  v_user_id := auth.uid();
  v_tenant_id := current_tenant_id();
  
  -- Update alert
  UPDATE inventory.reorder_alerts
  SET
    status = 'dismissed',
    dismissed_by = v_user_id,
    dismissed_at = now(),
    dismissed_reason = p_reason,
    updated_at = now()
  WHERE id = p_alert_id
    AND tenant_id = v_tenant_id
    AND status IN ('open', 'acknowledged');
    
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert not found or already dismissed';
  END IF;
END;
$$;


ALTER FUNCTION "inventory"."rpc_dismiss_alert"("p_alert_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_asset_assign"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_assigned_to_type" "text", "p_assigned_to_id" "uuid", "p_assigned_by_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_assignment_id UUID;
    v_asset RECORD;
    v_event_id TEXT;
    v_existing_assignment UUID;
BEGIN
    -- Validate
    IF p_tenant_id IS NULL OR p_asset_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id and asset_id are required';
    END IF;
    
    -- Generate event ID
    v_event_id := COALESCE(p_last_event_id, 'asset_assign_' || gen_random_uuid()::TEXT);
    
    -- Get asset
    SELECT * INTO v_asset
    FROM inventory.assets
    WHERE id = p_asset_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Asset not found';
    END IF;
    
    -- Check for existing active assignment
    SELECT id INTO v_existing_assignment
    FROM inventory.asset_assignments
    WHERE asset_id = p_asset_id
    AND tenant_id = p_tenant_id
    AND returned_at IS NULL;
    
    IF v_existing_assignment IS NOT NULL THEN
        RAISE EXCEPTION 'Asset already assigned - must return before reassigning';
    END IF;
    
    -- Create assignment (idempotent)
    INSERT INTO inventory.asset_assignments (
        tenant_id,
        asset_id,
        assigned_to_type,
        assigned_to_id,
        assigned_by_user_id,
        assigned_at,
        notes,
        last_event_id
    ) VALUES (
        p_tenant_id,
        p_asset_id,
        p_assigned_to_type,
        p_assigned_to_id,
        p_assigned_by_user_id,
        NOW(),
        p_notes,
        v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_assignment_id;
    
    -- If no ID returned, assignment already exists
    IF v_assignment_id IS NULL THEN
        SELECT id INTO v_assignment_id
        FROM inventory.asset_assignments
        WHERE tenant_id = p_tenant_id
        AND last_event_id = v_event_id;
        
        RETURN v_assignment_id;
    END IF;
    
    -- Update asset status
    UPDATE inventory.assets
    SET 
        status = 'assigned',
        updated_at = NOW()
    WHERE id = p_asset_id;
    
    -- Update asset_state read model
    INSERT INTO inventory.asset_state (
        id, tenant_id, asset_id, current_status, assigned_to_ref, last_movement_at
    ) VALUES (
        p_asset_id, p_tenant_id, p_asset_id, 'assigned',
        jsonb_build_object('type', p_assigned_to_type, 'id', p_assigned_to_id),
        NOW()
    )
    ON CONFLICT (tenant_id, asset_id) DO UPDATE
    SET 
        current_status = 'assigned',
        assigned_to_ref = jsonb_build_object('type', p_assigned_to_type, 'id', p_assigned_to_id),
        last_movement_at = NOW(),
        updated_at = NOW();
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'asset',
        p_event_type => 'asset.assigned',
        p_aggregate_type => 'asset',
        p_aggregate_id => p_asset_id,
        p_payload => jsonb_build_object(
            'asset_id', p_asset_id,
            'asset_tag', v_asset.asset_tag,
            'assignment_id', v_assignment_id,
            'assigned_to_type', p_assigned_to_type,
            'assigned_to_id', p_assigned_to_id
        )
    );
    
    RETURN v_assignment_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_asset_assign"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_assigned_to_type" "text", "p_assigned_to_id" "uuid", "p_assigned_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_asset_assign"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_assigned_to_type" "text", "p_assigned_to_id" "uuid", "p_assigned_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") IS 'Assigns asset to employee/vehicle/job (idempotent)';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_asset_return"("p_tenant_id" "uuid", "p_asset_id" "uuid", "p_return_condition" "text" DEFAULT 'good'::"text", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_assignment RECORD;
    v_asset RECORD;
    v_event_id TEXT;
BEGIN
    -- Generate event ID
    v_event_id := COALESCE(p_last_event_id, 'asset_return_' || gen_random_uuid()::TEXT);
    
    -- Get active assignment
    SELECT * INTO v_assignment
    FROM inventory.asset_assignments
    WHERE asset_id = p_asset_id
    AND tenant_id = p_tenant_id
    AND returned_at IS NULL;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'No active assignment found for asset';
    END IF;
    
    -- Get asset
    SELECT * INTO v_asset
    FROM inventory.assets
    WHERE id = p_asset_id
    AND tenant_id = p_tenant_id;
    
    -- Update assignment (idempotent check via last_event_id in notes)
    UPDATE inventory.asset_assignments
    SET 
        returned_at = NOW(),
        return_condition = p_return_condition,
        notes = COALESCE(notes, '') || E'\nReturn: ' || COALESCE(p_notes, ''),
        updated_at = NOW()
    WHERE id = v_assignment.id
    AND returned_at IS NULL; -- Double-check it hasn't been returned
    
    -- Update asset status based on condition
    UPDATE inventory.assets
    SET 
        status = CASE p_return_condition
            WHEN 'good' THEN 'available'
            WHEN 'damaged' THEN 'in_repair'
            WHEN 'needs_repair' THEN 'in_repair'
            ELSE 'out_of_service'
        END,
        updated_at = NOW()
    WHERE id = p_asset_id;
    
    -- Update asset_state read model
    UPDATE inventory.asset_state
    SET 
        current_status = CASE p_return_condition
            WHEN 'good' THEN 'available'
            WHEN 'damaged' THEN 'in_repair'
            WHEN 'needs_repair' THEN 'in_repair'
            ELSE 'out_of_service'
        END,
        assigned_to_ref = NULL,
        last_movement_at = NOW(),
        updated_at = NOW()
    WHERE asset_id = p_asset_id
    AND tenant_id = p_tenant_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'asset',
        p_event_type => 'asset.returned',
        p_aggregate_type => 'asset',
        p_aggregate_id => p_asset_id,
        p_payload => jsonb_build_object(
            'asset_id', p_asset_id,
            'asset_tag', v_asset.asset_tag,
            'assignment_id', v_assignment.id,
            'return_condition', p_return_condition,
            'days_assigned', EXTRACT(DAY FROM (NOW() - v_assignment.assigned_at))
        )
    );
    
    RETURN TRUE;
END;
$$;


