Migrate frontend to call supply_chain.rpc_create_receipt() directly.';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_release_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_cancelled_by_user_id" "uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_reservation RECORD;
    v_event_id TEXT;
BEGIN
    v_event_id := COALESCE(p_last_event_id, 'release_' || gen_random_uuid()::TEXT);
    
    -- Get reservation
    SELECT * INTO v_reservation
    FROM inventory.reservations
    WHERE id = p_reservation_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Reservation not found';
    END IF;
    
    IF v_reservation.status != 'active' THEN
        RAISE EXCEPTION 'Reservation cannot be cancelled in status: %', v_reservation.status;
    END IF;
    
    -- Update reservation
    UPDATE inventory.reservations
    SET 
        status = 'cancelled',
        cancelled_by_user_id = p_cancelled_by_user_id,
        updated_at = NOW()
    WHERE id = p_reservation_id;
    
    -- Release from stock_balances.qty_reserved
    UPDATE inventory.stock_balances
    SET 
        qty_reserved = qty_reserved - v_reservation.qty,
        updated_at = NOW()
    WHERE tenant_id = p_tenant_id
    AND catalog_item_id = v_reservation.catalog_item_id
    AND location_id = v_reservation.location_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'inventory',
        p_event_type => 'reservation.cancelled',
        p_aggregate_type => 'reservation',
        p_aggregate_id => p_reservation_id,
        p_payload => jsonb_build_object(
            'reservation_id', p_reservation_id,
            'catalog_item_id', v_reservation.catalog_item_id,
            'location_id', v_reservation.location_id,
            'qty', v_reservation.qty
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_release_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_cancelled_by_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_release_reservation"("p_tenant_id" "uuid", "p_reservation_id" "uuid", "p_cancelled_by_user_id" "uuid", "p_last_event_id" "text") IS 'Cancels reservation and releases reserved quantity';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_reserve"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_allocation_type" "text" DEFAULT NULL::"text", "p_job_ref" "jsonb" DEFAULT NULL::"jsonb", "p_external_order_ref" "text" DEFAULT NULL::"text", "p_needed_by" "date" DEFAULT NULL::"date", "p_expiration_date" "date" DEFAULT NULL::"date", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_reservation_id UUID;
    v_event_id TEXT;
    v_available_qty NUMERIC;
BEGIN
    -- Validate
    IF p_tenant_id IS NULL OR p_catalog_item_id IS NULL OR p_location_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id, catalog_item_id, and location_id are required';
    END IF;
    
    IF p_qty <= 0 THEN
        RAISE EXCEPTION 'qty must be greater than 0';
    END IF;
    
    -- Generate event ID
    v_event_id := COALESCE(p_last_event_id, 'reserve_' || gen_random_uuid()::TEXT);
    
    -- Check available quantity
    SELECT COALESCE(qty_available, 0) INTO v_available_qty
    FROM inventory.stock_balances
    WHERE tenant_id = p_tenant_id
    AND catalog_item_id = p_catalog_item_id
    AND location_id = p_location_id;
    
    IF v_available_qty < p_qty THEN
        RAISE EXCEPTION 'Insufficient available quantity: % available, % requested', 
            v_available_qty, p_qty;
    END IF;
    
    -- Create reservation (idempotent)
    INSERT INTO inventory.reservations (
        tenant_id,
        catalog_item_id,
        location_id,
        qty,
        status,
        allocation_type,
        job_ref,
        external_order_ref,
        needed_by,
        expiration_date,
        last_event_id
    ) VALUES (
        p_tenant_id,
        p_catalog_item_id,
        p_location_id,
        p_qty,
        'active',
        p_allocation_type,
        p_job_ref,
        p_external_order_ref,
        p_needed_by,
        p_expiration_date,
        v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_reservation_id;
    
    -- If no ID returned, reservation already exists
    IF v_reservation_id IS NULL THEN
        SELECT id INTO v_reservation_id
        FROM inventory.reservations
        WHERE tenant_id = p_tenant_id
        AND last_event_id = v_event_id;
        
        RETURN v_reservation_id;
    END IF;
    
    -- Update stock_balances.qty_reserved
    UPDATE inventory.stock_balances
    SET 
        qty_reserved = qty_reserved + p_qty,
        updated_at = NOW()
    WHERE tenant_id = p_tenant_id
    AND catalog_item_id = p_catalog_item_id
    AND location_id = p_location_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'inventory',
        p_event_type => 'reservation.created',
        p_aggregate_type => 'reservation',
        p_aggregate_id => v_reservation_id,
        p_payload => jsonb_build_object(
            'reservation_id', v_reservation_id,
            'catalog_item_id', p_catalog_item_id,
            'location_id', p_location_id,
            'qty', p_qty,
            'allocation_type', p_allocation_type,
            'external_order_ref', p_external_order_ref
        )
    );
    
    RETURN v_reservation_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_reserve"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_allocation_type" "text", "p_job_ref" "jsonb", "p_external_order_ref" "text", "p_needed_by" "date", "p_expiration_date" "date", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_reserve"("p_tenant_id" "uuid", "p_catalog_item_id" "uuid", "p_location_id" "uuid", "p_qty" numeric, "p_allocation_type" "text", "p_job_ref" "jsonb", "p_external_order_ref" "text", "p_needed_by" "date", "p_expiration_date" "date", "p_last_event_id" "text") IS 'Creates inventory reservation (idempotent, checks availability)';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_cancellation_reason" "text", "p_cancelled_by_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer RECORD;
BEGIN
    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    IF v_transfer.status NOT IN ('draft', 'in_transit') THEN
        RAISE EXCEPTION 'Transfer cannot be cancelled in status: %', v_transfer.status;
    END IF;
    
    UPDATE inventory.transfers
    SET 
        status = 'cancelled',
        cancellation_reason = p_cancellation_reason,
        cancelled_at = NOW(),
        updated_at = NOW()
    WHERE id = p_transfer_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'inventory',
        p_event_type => 'transfer.cancelled',
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'transfer_number', v_transfer.transfer_number,
            'reason', p_cancellation_reason
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_cancellation_reason" "text", "p_cancelled_by_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_cancel"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_cancellation_reason" "text", "p_cancelled_by_user_id" "uuid") IS 'Cancels a draft or in-transit transfer';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_create"("p_tenant_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_lines" "jsonb", "p_initiated_by_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer_id UUID;
    v_transfer_number TEXT;
    v_line JSONB;
    v_line_number INTEGER := 1;
    v_event_id TEXT;
BEGIN
    -- Validate tenant
    IF p_tenant_id IS NULL THEN
        RAISE EXCEPTION 'tenant_id is required';
    END IF;
    
    -- Validate locations
    IF p_from_location_id = p_to_location_id THEN
        RAISE EXCEPTION 'from_location_id and to_location_id must be different';
    END IF;
    
    -- Generate event ID if not provided
    v_event_id := COALESCE(p_last_event_id, 'transfer_create_' || gen_random_uuid()::TEXT);
    
    -- Generate transfer number
    SELECT 'TRF-' || to_char(NOW(), 'YYYYMMDD') || '-' || LPAD((
        SELECT COUNT(*) + 1 
        FROM inventory.transfers 
        WHERE tenant_id = p_tenant_id
        AND created_at::DATE = CURRENT_DATE
    )::TEXT, 4, '0')
    INTO v_transfer_number;
    
    -- Insert transfer header (idempotent)
    INSERT INTO inventory.transfers (
        tenant_id,
        transfer_number,
        from_location_id,
        to_location_id,
        status,
        initiated_by_user_id,
        notes,
        last_event_id
    ) VALUES (
        p_tenant_id,
        v_transfer_number,
        p_from_location_id,
        p_to_location_id,
        'draft',
        p_initiated_by_user_id,
        p_notes,
        v_event_id
    )
    ON CONFLICT (tenant_id, last_event_id) DO NOTHING
    RETURNING id INTO v_transfer_id;
    
    -- If no ID returned, transfer already exists (idempotency)
    IF v_transfer_id IS NULL THEN
        SELECT id INTO v_transfer_id
        FROM inventory.transfers
        WHERE tenant_id = p_tenant_id
        AND last_event_id = v_event_id;
        
        RETURN v_transfer_id;
    END IF;
    
    -- Insert lines
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        INSERT INTO inventory.transfer_lines (
            tenant_id,
            transfer_id,
            line_number,
            catalog_item_id,
            qty,
            last_event_id
        ) VALUES (
            p_tenant_id,
            v_transfer_id,
            v_line_number,
            (v_line->>'catalog_item_id')::UUID,
            (v_line->>'qty')::NUMERIC,
            v_event_id || '_line_' || v_line_number
        );
        
        v_line_number := v_line_number + 1;
    END LOOP;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'transfer.created',
        p_aggregate_type => 'transfer',
        p_aggregate_id => v_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', v_transfer_id,
            'transfer_number', v_transfer_number,
            'from_location_id', p_from_location_id,
            'to_location_id', p_to_location_id,
            'line_count', jsonb_array_length(p_lines)
        )
    );
    
    RETURN v_transfer_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_create"("p_tenant_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_lines" "jsonb", "p_initiated_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_create"("p_tenant_id" "uuid", "p_from_location_id" "uuid", "p_to_location_id" "uuid", "p_lines" "jsonb", "p_initiated_by_user_id" "uuid", "p_notes" "text", "p_last_event_id" "text") IS 'Creates transfer in draft status (idempotent)';



CREATE OR REPLACE FUNCTION "inventory"."rpc_inv_transfer_execute"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_transfer RECORD;
    v_line RECORD;
    v_correlation_id UUID;
    v_event_id TEXT;
    v_now TIMESTAMPTZ := NOW();
BEGIN
    -- Generate event ID
    v_event_id := COALESCE(p_last_event_id, 'transfer_execute_' || gen_random_uuid()::TEXT);
    
    -- Get transfer
    SELECT * INTO v_transfer
    FROM inventory.transfers
    WHERE id = p_transfer_id
    AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    IF v_transfer.status NOT IN ('draft', 'in_transit') THEN
        RAISE EXCEPTION 'Transfer cannot be executed in status: %', v_transfer.status;
    END IF;
    
    -- Generate correlation ID for paired entries
    v_correlation_id := gen_random_uuid();
    
    -- Process each line
    FOR v_line IN 
        SELECT * FROM inventory.transfer_lines
        WHERE transfer_id = p_transfer_id
        ORDER BY line_number
    LOOP
        -- Debit from source location (transferred_out)
        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.from_location_id,
            p_quantity_delta => -v_line.qty,
            p_movement_type => 'transferred_out',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Transfer to ' || (SELECT name FROM inventory.locations WHERE id = v_transfer.to_location_id),
            p_notes => 'Transfer #' || v_transfer.transfer_number,
            p_correlation_id => v_correlation_id,
            p_occurred_at => v_now,
            p_created_by_user_id => p_received_by_user_id,
            p_last_event_id => v_event_id || '_out_' || v_line.line_number
        );
        
        -- Credit to destination location (transferred_in)
        PERFORM inventory.insert_stock_movement(
            p_tenant_id => p_tenant_id,
            p_catalog_item_id => v_line.catalog_item_id,
            p_location_id => v_transfer.to_location_id,
            p_quantity_delta => v_line.qty,
            p_movement_type => 'transferred_in',
            p_source_ref_type => 'transfer',
            p_source_ref_id => p_transfer_id,
            p_unit_cost => NULL,
            p_reason => 'Transfer from ' || (SELECT name FROM inventory.locations WHERE id = v_transfer.from_location_id),
            p_notes => 'Transfer #' || v_transfer.transfer_number,
            p_correlation_id => v_correlation_id,
            p_occurred_at => v_now,
            p_created_by_user_id => p_received_by_user_id,
            p_last_event_id => v_event_id || '_in_' || v_line.line_number
        );
    END LOOP;
    
    -- Update transfer status
    UPDATE inventory.transfers
    SET 
        status = 'completed',
        received_by_user_id = p_received_by_user_id,
        completed_at = v_now,
        updated_at = v_now
    WHERE id = p_transfer_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'inventory',
        p_event_type => 'transfer.completed',
        p_aggregate_type => 'transfer',
        p_aggregate_id => p_transfer_id,
        p_payload => jsonb_build_object(
            'transfer_id', p_transfer_id,
            'transfer_number', v_transfer.transfer_number,
            'from_location_id', v_transfer.from_location_id,
            'to_location_id', v_transfer.to_location_id,
            'correlation_id', v_correlation_id
        )
    );
    
    RETURN TRUE;
END;
$$;


ALTER FUNCTION "inventory"."rpc_inv_transfer_execute"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_inv_transfer_execute"("p_tenant_id" "uuid", "p_transfer_id" "uuid", "p_received_by_user_id" "uuid", "p_last_event_id" "text") IS 'Executes transfer by writing paired ledger entries (idempotent)';



CREATE OR REPLACE FUNCTION "inventory"."rpc_issue_inventory"("p_location_id" "uuid", "p_items" "jsonb", "p_issued_to_type" "text" DEFAULT NULL::"text", "p_issued_to_ref" "text" DEFAULT NULL::"text", "p_reason" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
  v_tenant_id UUID;
  v_item JSONB;
  v_event_id TEXT;
  v_issued_count INT := 0;
  v_result JSONB;
BEGIN
  v_tenant_id := (auth.jwt() ->> 'tenant_id')::UUID;
  
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  
  -- Process each item
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_event_id := 'issue-' || gen_random_uuid()::TEXT || '-' || extract(epoch from now())::TEXT;
    
    -- Check availability
    IF NOT EXISTS (
      SELECT 1 FROM inventory.stock_balances
      WHERE tenant_id = v_tenant_id
        AND catalog_item_id = (v_item->>'catalog_item_id')::UUID
        AND location_id = p_location_id
        AND qty_available >= (v_item->>'qty_issued')::NUMERIC
    ) THEN
      RAISE EXCEPTION 'Insufficient stock for item % at location %',
        v_item->>'catalog_item_id', p_location_id;
    END IF;
    
    -- Insert inventory event
    INSERT INTO inventory.inventory_events (
      tenant_id,
      catalog_item_id,
      location_id,
      event_type,
      quantity_delta,
      payload,
      occurred_at,
      actor_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      (v_item->>'catalog_item_id')::UUID,
      p_location_id,
      'issue',
      -(v_item->>'qty_issued')::NUMERIC, -- NEGATIVE
      jsonb_build_object(
        'issued_to_type', p_issued_to_type,
        'issued_to_ref', p_issued_to_ref,
        'reason', p_reason
      ),
      NOW(),
      (auth.jwt() ->> 'user_id')::UUID,
      v_event_id
    );
    
    -- Insert stock movement
    INSERT INTO inventory.stock_movements (
      tenant_id,
      catalog_item_id,
      location_id,
      quantity_delta,
      movement_type,
      source_ref_type,
      reason,
      notes,
      occurred_at,
      created_by_user_id,
      last_event_id
    ) VALUES (
      v_tenant_id,
      (v_item->>'catalog_item_id')::UUID,
      p_location_id,
      -(v_item->>'qty_issued')::NUMERIC, -- NEGATIVE
      'issued',
      p_issued_to_type,
      p_reason,
      p_notes,
      NOW(),
      (auth.jwt() ->> 'user_id')::UUID,
      v_event_id
    );
    
    -- Update stock balances
    UPDATE inventory.stock_balances
    SET
      qty_on_hand = qty_on_hand - (v_item->>'qty_issued')::NUMERIC,
      qty_available = qty_available - (v_item->>'qty_issued')::NUMERIC,
      last_event_id = v_event_id,
      updated_at = NOW()
    WHERE tenant_id = v_tenant_id
      AND catalog_item_id = (v_item->>'catalog_item_id')::UUID
      AND location_id = p_location_id;
    
    v_issued_count := v_issued_count + 1;
  END LOOP;
  
  v_result := jsonb_build_object(
    'success', true,
    'issued_count', v_issued_count,
    'location_id', p_location_id,
    'issued_to', jsonb_build_object('type', p_issued_to_type, 'ref', p_issued_to_ref)
  );
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION "inventory"."rpc_issue_inventory"("p_location_id" "uuid", "p_items" "jsonb", "p_issued_to_type" "text", "p_issued_to_ref" "text", "p_reason" "text", "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_issue_inventory"("p_location_id" "uuid", "p_items" "jsonb", "p_issued_to_type" "text", "p_issued_to_ref" "text", "p_reason" "text", "p_notes" "text") IS 'Frontend RPC: Issue inventory from a location.
Validates availability, creates events and movements, updates balances.
Returns: {success, issued_count, location_id, issued_to}';



CREATE OR REPLACE FUNCTION "inventory"."rpc_mark_alert_ordered"("p_alert_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tenant_id UUID;
BEGIN
  v_tenant_id := current_tenant_id();
  
  -- Update alert
  UPDATE inventory.reorder_alerts
  SET
    status = 'ordered',
    updated_at = now()
  WHERE id = p_alert_id
    AND tenant_id = v_tenant_id
    AND status IN ('open', 'acknowledged');
    
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert not found or already processed';
  END IF;
END;
$$;


ALTER FUNCTION "inventory"."rpc_mark_alert_ordered"("p_alert_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."rpc_reverse_stock_movement"("p_tenant_id" "uuid", "p_movement_id" "uuid", "p_reason" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_last_event_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
    v_movement RECORD;
    v_reversal_id UUID;
    v_event_id TEXT;
BEGIN
    v_event_id := COALESCE(p_last_event_id, 'reversal_' || gen_random_uuid()::TEXT);
    
    -- Get original movement
    SELECT * INTO v_movement
    FROM inventory.stock_movements
    WHERE id = p_movement_id
      AND tenant_id = p_tenant_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Stock movement not found';
    END IF;
    
    -- Validate can be reversed
    IF v_movement.posting_status = 'reversed' THEN
        RAISE EXCEPTION 'Movement already reversed';
    END IF;
    
    IF v_movement.posting_status = 'pending' THEN
        RAISE EXCEPTION 'Cannot reverse pending movement, delete it instead';
    END IF;
    
    -- Check if already has reversal
    IF EXISTS (
        SELECT 1 FROM inventory.stock_movements 
        WHERE reversal_ref_id = p_movement_id 
        AND posting_status = 'posted'
    ) THEN
        RAISE EXCEPTION 'Movement already has an active reversal';
    END IF;
    
    -- Create offsetting movement
    v_reversal_id := inventory.insert_stock_movement(
        p_tenant_id => p_tenant_id,
        p_catalog_item_id => v_movement.catalog_item_id,
        p_location_id => v_movement.location_id,
        p_quantity_delta => -v_movement.quantity_delta,  -- Negate original delta
        p_movement_type => 'adjusted',
        p_source_ref_type => 'reversal',
        p_source_ref_id => p_movement_id,
        p_unit_cost => v_movement.unit_cost,
        p_reason => 'REVERSAL: ' || COALESCE(p_reason, 'Correcting erroneous movement'),
        p_notes => 'Reverses movement ' || p_movement_id::TEXT || '. Original: ' || COALESCE(v_movement.notes, 'N/A'),
        p_correlation_id => v_movement.correlation_id,
        p_occurred_at => NOW(),
        p_created_by_user_id => p_user_id,
        p_last_event_id => v_event_id
    );
    
    -- Update reversal reference
    UPDATE inventory.stock_movements
    SET reversal_ref_id = p_movement_id
    WHERE id = v_reversal_id;
    
    -- Mark original as reversed
    UPDATE inventory.stock_movements
    SET posting_status = 'reversed'
    WHERE id = p_movement_id;
    
    -- Publish event
    PERFORM inventory.publish_event(
        p_tenant_id => p_tenant_id,
        p_scope => 'tenant',
        p_event_type => 'stock_movement.reversed',
        p_aggregate_type => 'stock_movement',
        p_aggregate_id => p_movement_id,
        p_payload => jsonb_build_object(
            'original_movement_id', p_movement_id,
            'reversal_movement_id', v_reversal_id,
            'catalog_item_id', v_movement.catalog_item_id,
            'location_id', v_movement.location_id,
            'original_delta', v_movement.quantity_delta,
            'reversal_delta', -v_movement.quantity_delta,
            'reason', p_reason
        ),
        p_metadata => jsonb_build_object(
            'reversed_by_user_id', p_user_id,
            'reversed_at', NOW()
        )
    );
    
    RETURN v_reversal_id;
END;
$$;


ALTER FUNCTION "inventory"."rpc_reverse_stock_movement"("p_tenant_id" "uuid", "p_movement_id" "uuid", "p_reason" "text", "p_user_id" "uuid", "p_last_event_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."rpc_reverse_stock_movement"("p_tenant_id" "uuid", "p_movement_id" "uuid", "p_reason" "text", "p_user_id" "uuid", "p_last_event_id" "text") IS 'Reverses a stock movement by creating an offsetting entry. Original marked as reversed, new movement references original. Idempotent via last_event_id.';



CREATE OR REPLACE FUNCTION "inventory"."set_audit_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- On INSERT, set created_by from auth.uid()
    IF TG_OP = 'INSERT' THEN
        NEW.created_by = auth.uid();
        NEW.updated_by = auth.uid();
    -- On UPDATE, only update updated_by
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.updated_by = auth.uid();
        -- Prevent changing created_by
        IF OLD.created_by IS NOT NULL THEN
            NEW.created_by = OLD.created_by;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."set_audit_fields"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."set_audit_fields"() IS 'Automatically sets created_by and updated_by from auth.uid()';



CREATE OR REPLACE FUNCTION "inventory"."setup_test_scenario"() RETURNS TABLE("tenant_id" "uuid", "location_id" "uuid", "item1_id" "uuid", "item2_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_tenant_id UUID;
    v_location_id UUID;
    v_item1_id UUID;
    v_item2_id UUID;
BEGIN
    -- Create tenant
    v_tenant_id := inventory.create_test_tenant('Epic Inventory Test');
    
    -- Create location
    v_location_id := inventory.create_test_location(v_tenant_id, 'Main Warehouse');
    
    -- Create items
    v_item1_id := inventory.create_test_item(v_tenant_id, 'WIDGET-100', 'Standard Widget', 'stock');
    v_item2_id := inventory.create_test_item(v_tenant_id, 'GADGET-200', 'Premium Gadget', 'stock');
    
    -- Add stock
    PERFORM inventory.add_test_stock(v_tenant_id, v_item1_id, v_location_id, 100);
    PERFORM inventory.add_test_stock(v_tenant_id, v_item2_id, v_location_id, 50);
    
    RETURN QUERY SELECT v_tenant_id, v_location_id, v_item1_id, v_item2_id;
END;
$$;


ALTER FUNCTION "inventory"."setup_test_scenario"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."setup_test_scenario"() IS 'Quick test data setup: tenant, location, 2 items with stock';



CREATE OR REPLACE FUNCTION "inventory"."soft_delete_catalog_item"("p_item_id" "uuid", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_has_stock BOOLEAN;
BEGIN
    -- Check if item has any stock
    SELECT EXISTS(
        SELECT 1 FROM inventory.stock_balances 
        WHERE catalog_item_id = p_item_id AND qty_on_hand > 0
    ) INTO v_has_stock;
    
    IF v_has_stock THEN
        RAISE EXCEPTION 'Cannot delete item with existing stock on hand'
        USING HINT = 'Transfer or adjust stock to zero before deleting';
    END IF;
    
    -- Soft delete
    UPDATE inventory.catalog_items
    SET 
        deleted_at = NOW(),
        deleted_by_user_id = p_user_id,
        updated_at = NOW()
    WHERE id = p_item_id;
    
    RETURN FOUND;
END;
$$;


ALTER FUNCTION "inventory"."soft_delete_catalog_item"("p_item_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."soft_delete_catalog_item"("p_item_id" "uuid", "p_user_id" "uuid") IS 'Safely soft-deletes a catalog item after validating no stock exists';



CREATE OR REPLACE FUNCTION "inventory"."update_updated_at_column"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."update_updated_at_column"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "inventory"."validate_catalog_item_active"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_is_active BOOLEAN;
  v_item_sku TEXT;
BEGIN
  -- Check if catalog item is active
  SELECT active, sku INTO v_is_active, v_item_sku
  FROM inventory.catalog_items
  WHERE id = NEW.catalog_item_id;

  IF NOT v_is_active THEN
    RAISE EXCEPTION 'Cannot create PO line for inactive item: % (SKU: %)', 
      NEW.catalog_item_id, v_item_sku
    USING HINT = 'Reactivate the catalog item before adding to purchase orders';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_catalog_item_active"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_catalog_item_active"() IS 'Prevents PO lines from being created for inactive catalog items';



CREATE OR REPLACE FUNCTION "inventory"."validate_reservation_availability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_available NUMERIC;
    v_item_sku TEXT;
    v_location_name TEXT;
BEGIN
    -- Only validate for active reservations
    IF NEW.status != 'active' THEN
        RETURN NEW;
    END IF;
    
    -- Get current available quantity and descriptive info
    SELECT 
        COALESCE(sb.qty_available, 0),
        ci.sku,
        l.name
    INTO v_available, v_item_sku, v_location_name
    FROM inventory.stock_balances sb
    JOIN inventory.catalog_items ci ON ci.id = NEW.catalog_item_id
    JOIN inventory.locations l ON l.id = NEW.location_id
    WHERE sb.tenant_id = NEW.tenant_id
      AND sb.catalog_item_id = NEW.catalog_item_id
      AND sb.location_id = NEW.location_id;
    
    -- If no stock balance exists, available is 0
    v_available := COALESCE(v_available, 0);
    
    IF NEW.qty > v_available THEN
        RAISE EXCEPTION 'Insufficient available stock for reservation: % units requested for item "%" at location "%", but only % units available',
            NEW.qty, v_item_sku, v_location_name, v_available
        USING 
            ERRCODE = 'check_violation',
            HINT = 'Check stock availability before creating reservation or receive more inventory';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_reservation_availability"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_reservation_availability"() IS 'Prevents over-booking by validating reservation quantity against available stock';



CREATE OR REPLACE FUNCTION "inventory"."validate_single_active_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_count INTEGER;
    v_existing_assignment RECORD;
BEGIN
    -- Only validate for active assignments
    IF NEW.returned_at IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- Check for existing active assignment
    SELECT 
        aa.id,
        aa.assigned_to_type,
        aa.assigned_to_id,
        aa.assigned_at
    INTO v_existing_assignment
    FROM inventory.asset_assignments aa
    WHERE aa.asset_id = NEW.asset_id
      AND aa.returned_at IS NULL
      AND aa.id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::UUID)
    LIMIT 1;
    
    IF FOUND THEN
        RAISE EXCEPTION 'Asset % already has an active assignment (ID: %, assigned to % % on %)',
            NEW.asset_id,
            v_existing_assignment.id,
            v_existing_assignment.assigned_to_type,
            v_existing_assignment.assigned_to_id,
            v_existing_assignment.assigned_at
        USING 
            ERRCODE = 'unique_violation',
            HINT = 'Return the existing assignment before creating a new one';
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "inventory"."validate_single_active_assignment"() OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."validate_single_active_assignment"() IS 'Ensures only one active assignment per asset at any time';



CREATE OR REPLACE FUNCTION "inventory"."verify_quantity_integrity"("p_tenant_id" "uuid") RETURNS TABLE("check_name" "text", "status" "text", "details" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Check 1: No negative on-hand (after accounting for all movements)
    RETURN QUERY
    SELECT
        'No Negative On-Hand'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'All locations have non-negative on-hand quantities'
            ELSE COUNT(*)::TEXT || ' locations have negative on-hand'
        END::TEXT
    FROM inventory.v_on_hand_by_item_location
    WHERE tenant_id = p_tenant_id
      AND qty_on_hand < 0;
    
    -- Check 2: Reserved doesn't exceed on-hand
    RETURN QUERY
    SELECT
        'Reserved <= On-Hand'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'WARNING' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'All reservations are backed by on-hand stock'
            ELSE COUNT(*)::TEXT || ' locations have over-reserved stock'
        END::TEXT
    FROM inventory.v_core_quantities
    WHERE tenant_id = p_tenant_id
      AND qty_reserved > qty_on_hand;
    
    -- Check 3: All stock movements have last_event_id
    RETURN QUERY
    SELECT
        'Stock Movements Idempotency'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'All stock movements have last_event_id'
            ELSE COUNT(*)::TEXT || ' movements missing last_event_id'
        END::TEXT
    FROM inventory.stock_movements
    WHERE tenant_id = p_tenant_id
      AND last_event_id IS NULL;
    
    -- Check 4: No direct quantity columns on catalog_items
    RETURN QUERY
    SELECT
        'No Quantity on Master Data'::TEXT,
        'PASS'::TEXT,
        'Catalog items correctly have no qty_on_hand column'::TEXT
    WHERE NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'inventory'
          AND table_name = 'catalog_items'
          AND column_name IN ('qty_on_hand', 'quantity', 'stock_level')
    );
    
    -- Check 5: All active reservations have future or null needed_by
    RETURN QUERY
    SELECT
        'Reservation Expiry'::TEXT,
        CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'WARNING' END::TEXT,
        CASE WHEN COUNT(*) = 0 
            THEN 'No overdue active reservations'
            ELSE COUNT(*)::TEXT || ' active reservations past needed_by date'
        END::TEXT
    FROM inventory.reservations
    WHERE tenant_id = p_tenant_id
      AND status = 'active'
      AND needed_by < CURRENT_DATE;
END;
$$;


ALTER FUNCTION "inventory"."verify_quantity_integrity"("p_tenant_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "inventory"."verify_quantity_integrity"("p_tenant_id" "uuid") IS 'Run integrity checks on inventory quantities and statuses';



