CREATE OR REPLACE FUNCTION "public"."emit_event"("p_event_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid", "p_scope" "text" DEFAULT 'tenant'::"text", "p_aggregate_type" "text" DEFAULT NULL::"text", "p_aggregate_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_id UUID;
    v_event_name TEXT;
    v_event_version INT;
BEGIN
    -- Parse event_type to extract event_name and version if provided
    -- Format: "inventory.stock.adjusted" or "inventory.stock.adjusted@2"
    IF p_event_type LIKE '%@%' THEN
        v_event_name := split_part(p_event_type, '@', 1);
        v_event_version := split_part(p_event_type, '@', 2)::int;
    ELSE
        v_event_name := p_event_type;
        v_event_version := 1;  -- Default version
    END IF;

    -- Call existing publish_event function (with event_name signature)
    v_event_id := inventory.publish_event(
        p_tenant_id := p_tenant_id,
        p_scope := p_scope,
        p_event_name := v_event_name,
        p_aggregate_type := COALESCE(p_aggregate_type, v_event_name),
        p_aggregate_id := COALESCE(p_aggregate_id, gen_random_uuid()),
        p_payload := p_payload,
        p_event_version := v_event_version,
        p_metadata := p_metadata
    );

    RETURN v_event_id;
END;
$$;


ALTER FUNCTION "public"."emit_event"("p_event_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid", "p_scope" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."emit_event"("p_event_type" "text", "p_payload" "jsonb", "p_tenant_id" "uuid", "p_scope" "text", "p_aggregate_type" "text", "p_aggregate_id" "uuid", "p_metadata" "jsonb") IS 'Standard event emission interface - wraps inventory.publish_event for hub protocol compliance';



CREATE OR REPLACE FUNCTION "public"."get_event_catalog_stats"() RETURNS TABLE("event_name" "text", "version" integer, "status" "text", "total_emitted" bigint, "last_emitted_at" timestamp with time zone, "pending_count" bigint, "published_count" bigint, "failed_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        ed.event_name,
        ed.version,
        ed.status,
        COUNT(eo.id) as total_emitted,
        MAX(eo.created_at) as last_emitted_at,
        COUNT(eo.id) FILTER (WHERE eo.status = 'pending') as pending_count,
        COUNT(eo.id) FILTER (WHERE eo.status = 'published') as published_count,
        COUNT(eo.id) FILTER (WHERE eo.status = 'failed') as failed_count
    FROM public.event_definitions ed
    LEFT JOIN inventory.events_outbox eo ON ed.event_name = eo.event_name AND ed.version = eo.event_version
    GROUP BY ed.event_name, ed.version, ed.status
    ORDER BY ed.event_name, ed.version DESC;
END;
$$;


ALTER FUNCTION "public"."get_event_catalog_stats"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_event_catalog_stats"() IS 'Get statistics for each event in the catalog';



CREATE OR REPLACE FUNCTION "public"."register_event"("p_event_name" "text", "p_version" integer DEFAULT 1, "p_producer" "text" DEFAULT 'inventory'::"text", "p_description" "text" DEFAULT ''::"text", "p_payload_schema" "jsonb" DEFAULT NULL::"jsonb", "p_example_payload" "jsonb" DEFAULT NULL::"jsonb", "p_status" "text" DEFAULT 'active'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_definition_id UUID;
BEGIN
    -- Upsert event definition
    INSERT INTO public.event_definitions (
        event_name,
        version,
        producer,
        description,
        payload_schema,
        example_payload,
        status,
        created_at,
        updated_at
    ) VALUES (
        p_event_name,
        p_version,
        p_producer,
        p_description,
        p_payload_schema,
        p_example_payload,
        p_status,
        NOW(),
        NOW()
    )
    ON CONFLICT (event_name, version) 
    DO UPDATE SET
        description = EXCLUDED.description,
        payload_schema = EXCLUDED.payload_schema,
        example_payload = EXCLUDED.example_payload,
        status = EXCLUDED.status,
        updated_at = NOW()
    RETURNING id INTO v_definition_id;

    RETURN v_definition_id;
END;
$$;


