CREATE OR REPLACE FUNCTION "supply_chain"."auto_match_expenses_on_receipt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'inventory', 'public'
    AS $$
DECLARE
    v_po RECORD;
    v_total_received NUMERIC;
    v_matched_count INTEGER := 0;
    v_tolerance_pct NUMERIC := 0.05; -- 5% tolerance
    v_vendor_id UUID;
BEGIN
    -- Get PO details
    SELECT * INTO v_po
    FROM inventory.purchase_orders
    WHERE id = NEW.po_id;
    
    IF NOT FOUND OR v_po.vendor_location_id IS NULL THEN
        RETURN NEW;
    END IF;
    
    -- Get vendor_id from vendor_location
    SELECT vendor_id INTO v_vendor_id
    FROM inventory.locations
    WHERE id = v_po.vendor_location_id;
    
    IF v_vendor_id IS NULL THEN
        RETURN NEW;
    END IF;
    
    -- Calculate total value of received items
    SELECT COALESCE(SUM(rl.qty_received * rl.unit_cost), 0)
    INTO v_total_received
    FROM inventory.receipt_lines rl
    WHERE rl.receipt_id = NEW.id;
    
    -- Skip if no value to match
    IF v_total_received = 0 THEN
        RETURN NEW;
    END IF;
    
    -- Match unmatched expenses for this vendor with similar amounts
    WITH matching_expenses AS (
        SELECT ae.id, ae.amount,
               ABS(ae.amount - v_total_received) AS amount_diff,
               (ABS(ae.amount - v_total_received) / NULLIF(v_total_received, 0)) AS diff_pct
        FROM inventory.accounting_expenses ae
        WHERE ae.tenant_id = NEW.tenant_id
          AND ae.status = 'posted'
          AND ae.vendor_id = v_vendor_id
          AND ae.expense_date >= v_po.order_date - INTERVAL '30 days'
          AND ae.expense_date <= NEW.received_at + INTERVAL '7 days'
          AND (ABS(ae.amount - v_total_received) / NULLIF(v_total_received, 0)) <= v_tolerance_pct
        ORDER BY diff_pct ASC
        LIMIT 1
    )
    UPDATE inventory.accounting_expenses ae
    SET 
        status = 'matched',
        po_id = v_po.id,
        matched_at = NOW(),
        updated_at = NOW()
    FROM matching_expenses me
    WHERE ae.id = me.id;
    
    GET DIAGNOSTICS v_matched_count = ROW_COUNT;
    
    -- Log matching result
    IF v_matched_count > 0 THEN
        RAISE NOTICE 'Auto-matched % expense(s) for PO % (receipt %)', 
            v_matched_count, v_po.po_number, NEW.id;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."auto_match_expenses_on_receipt"() OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."auto_match_expenses_on_receipt"() IS 'Automatically matches accounting_expenses to POs when receipts are created. Uses vendor + amount tolerance (±5%).';



CREATE OR REPLACE FUNCTION "supply_chain"."emit_po_status_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_event_name TEXT;
    v_payload JSONB;
    v_line_count INTEGER;
    v_total_value NUMERIC;
BEGIN
    -- Get line count and total value
    SELECT COUNT(*), COALESCE(SUM(qty_ordered * COALESCE(unit_cost, 0)), 0)
    INTO v_line_count, v_total_value
    FROM supply_chain.purchase_order_lines
    WHERE po_id = NEW.id;

    IF TG_OP = 'INSERT' THEN
        v_event_name := 'supply_chain.purchase_order.created';
        v_payload := jsonb_build_object(
            'po_id', NEW.id,
            'po_number', NEW.po_number,
            'vendor_id', NEW.vendor_location_id,
            'order_date', NEW.order_date,
            'expected_delivery_date', NEW.expected_delivery_date,
            'line_items_count', v_line_count,
            'total_value', v_total_value,
            'tenant_id', NEW.tenant_id,
            'created_at', NEW.created_at
        );
    ELSIF TG_OP = 'UPDATE' THEN
        -- Detect status changes
        IF OLD.status != NEW.status THEN
            CASE NEW.status
                WHEN 'submitted' THEN
                    v_event_name := 'supply_chain.purchase_order.submitted';
                    v_payload := jsonb_build_object(
                        'po_id', NEW.id,
                        'po_number', NEW.po_number,
                        'tenant_id', NEW.tenant_id,
                        'submitted_at', NEW.updated_at
                    );
                WHEN 'approved' THEN
                    v_event_name := 'supply_chain.purchase_order.approved';
                    v_payload := jsonb_build_object(
                        'po_id', NEW.id,
                        'po_number', NEW.po_number,
                        'approved_by_user_id', NEW.approved_by_user_id,
                        'tenant_id', NEW.tenant_id,
                        'approved_at', NEW.approved_at
                    );
                WHEN 'cancelled' THEN
                    v_event_name := 'supply_chain.purchase_order.cancelled';
                    v_payload := jsonb_build_object(
                        'po_id', NEW.id,
                        'po_number', NEW.po_number,
                        'tenant_id', NEW.tenant_id,
                        'cancelled_at', NEW.updated_at
                    );
                WHEN 'closed' THEN
                    v_event_name := 'supply_chain.purchase_order.closed';
                    v_payload := jsonb_build_object(
                        'po_id', NEW.id,
                        'po_number', NEW.po_number,
                        'total_lines', v_line_count,
                        'tenant_id', NEW.tenant_id,
                        'closed_at', NEW.updated_at
                    );
                WHEN 'in_transit' THEN
                    v_event_name := 'supply_chain.purchase_order.in_transit';
                    v_payload := jsonb_build_object(
                        'po_id', NEW.id,
                        'po_number', NEW.po_number,
                        'vendor_id', NEW.vendor_location_id,
                        'tenant_id', NEW.tenant_id,
                        'shipped_at', NEW.updated_at
                    );
                WHEN 'received' THEN
                    v_event_name := 'supply_chain.purchase_order.received';
                    v_payload := jsonb_build_object(
                        'po_id', NEW.id,
                        'po_number', NEW.po_number,
                        'total_lines', v_line_count,
                        'tenant_id', NEW.tenant_id,
                        'received_at', NEW.updated_at
                    );
                ELSE
                    RETURN NEW; -- No event for other statuses
            END CASE;
        ELSE
            RETURN NEW; -- No status change
        END IF;
    END IF;
    
    -- Emit event
    PERFORM public.emit_event(
        v_event_name,
        v_payload,
        NEW.tenant_id
    );
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "supply_chain"."emit_po_status_event"() OWNER TO "postgres";


COMMENT ON FUNCTION "supply_chain"."emit_po_status_event"() IS 'Emits events for purchase order creation and status changes (FIXED: uses vendor_location_id)';



