);


ALTER TABLE "inventory"."cycle_count_variance_thresholds" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."cycle_count_variance_thresholds" IS 'Defines variance thresholds for cycle count approval';



CREATE TABLE IF NOT EXISTS "inventory"."cycle_counts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
