    CONSTRAINT "item_location_par_levels_reorder_point_check" CHECK ((("reorder_point" IS NULL) OR ("reorder_point" >= "min_qty"))),
    CONSTRAINT "item_location_par_levels_safety_stock_check" CHECK (("safety_stock" >= (0)::numeric))
);


ALTER TABLE "inventory"."item_location_par_levels" OWNER TO "postgres";


