    CONSTRAINT "item_substitutions_not_self_reference" CHECK (("item_id" <> "substitute_item_id")),
    CONSTRAINT "item_substitutions_priority_check" CHECK (("priority" > 0))
);


ALTER TABLE "inventory"."item_substitutions" OWNER TO "postgres";


