    "external_order_ref" "text",
    CONSTRAINT "chk_reservation_qty_positive" CHECK (("qty" > (0)::numeric)),
    CONSTRAINT "reservations_allocation_type_check" CHECK ((("allocation_type" IS NULL) OR ("allocation_type" = ANY (ARRAY['job'::"text", 'project'::"text", 'customer_order'::"text", 'internal_order'::"text", 'other'::"text"])))),
    CONSTRAINT "reservations_qty_check" CHECK (("qty" > (0)::numeric)),
    CONSTRAINT "reservations_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'fulfilled'::"text", 'released'::"text", 'expired'::"text"])))
);


