CREATE TABLE IF NOT EXISTS "inventory"."stock_movements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "catalog_item_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "quantity_delta" numeric(18,4) NOT NULL,
    "movement_type" "text" NOT NULL,
    "source_ref_type" "text",
    "source_ref_id" "uuid",
    "unit_cost" numeric(18,4),
    "currency" "text" DEFAULT 'USD'::"text",
    "reason" "text",
    "notes" "text",
    "correlation_id" "uuid",
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by_user_id" "uuid",
    "last_event_id" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "posting_status" "text" DEFAULT 'posted'::"text",
    "reversal_ref_id" "uuid",
    CONSTRAINT "chk_quantity_delta_not_zero" CHECK (("quantity_delta" <> (0)::numeric)),
    CONSTRAINT "stock_movements_movement_type_check" CHECK (("movement_type" = ANY (ARRAY['received'::"text", 'issued'::"text", 'adjusted'::"text", 'transferred_in'::"text", 'transferred_out'::"text", 'damaged'::"text", 'returned'::"text", 'counted'::"text", 'reserved'::"text", 'unreserved'::"text", 'consumed'::"text"]))),
    CONSTRAINT "stock_movements_posting_status_check" CHECK (("posting_status" = ANY (ARRAY['posted'::"text", 'reversed'::"text", 'pending'::"text"])))
);


ALTER TABLE "inventory"."stock_movements" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."stock_movements" IS 'Stock movement ledger - CANDIDATE FOR PARTITIONING by occurred_at (monthly)';



COMMENT ON COLUMN "inventory"."stock_movements"."quantity_delta" IS 'Change in quantity (+ or -)';



COMMENT ON COLUMN "inventory"."stock_movements"."movement_type" IS 'Type of stock change: received/issued/adjusted/transferred_in/transferred_out/damaged/returned/counted/reserved/unreserved/consumed';



COMMENT ON COLUMN "inventory"."stock_movements"."correlation_id" IS 'Links transfer pairs (from/to)';



COMMENT ON COLUMN "inventory"."stock_movements"."last_event_id" IS 'Idempotency key for event processing';



COMMENT ON COLUMN "inventory"."stock_movements"."posting_status" IS 'Ledger entry status: posted/reversed/pending';



COMMENT ON COLUMN "inventory"."stock_movements"."reversal_ref_id" IS 'For reversed movements, references the original movement being reversed';



COMMENT ON CONSTRAINT "chk_quantity_delta_not_zero" ON "inventory"."stock_movements" IS 'Prevents meaningless movements with zero quantity delta';



CREATE TABLE IF NOT EXISTS "inventory"."transfer_lines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "transfer_id" "uuid" NOT NULL,
