    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "transfer_lines_qty_check" CHECK (("qty" > (0)::numeric))
);


ALTER TABLE "inventory"."transfer_lines" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."transfer_lines" IS 'Transfer line items - what items and quantities are being transferred';



CREATE TABLE IF NOT EXISTS "inventory"."transfers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "transfer_number" "text" NOT NULL,
    "from_location_id" "uuid" NOT NULL,
    "to_location_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "initiated_by_user_id" "uuid",
    "received_by_user_id" "uuid",
    "initiated_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "cancelled_at" timestamp with time zone,
    "cancellation_reason" "text",
    "notes" "text",
    "last_event_id" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "transfers_different_locations" CHECK (("from_location_id" <> "to_location_id")),
    CONSTRAINT "transfers_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'in_transit'::"text", 'completed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "inventory"."transfers" OWNER TO "postgres";


COMMENT ON TABLE "inventory"."transfers" IS 'Transfer operations should use SERIALIZABLE isolation:
    BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
      -- Create transfer + lines + stock movements
    COMMIT;';



COMMENT ON COLUMN "inventory"."transfers"."last_event_id" IS 'Idempotency key for transfer creation/execution';



CREATE OR REPLACE VIEW "inventory"."v_assets_assigned" AS
 SELECT "aa"."tenant_id",
    "aa"."asset_id",
    "a"."asset_tag",
    "a"."serial_number",
    "ci"."sku",
    "ci"."name" AS "item_name",
    "aa"."assigned_to_type",
    "aa"."assigned_to_id",
    "aa"."assigned_by_user_id",
    "aa"."assigned_at",
    "aa"."notes",
    EXTRACT(day FROM ("now"() - "aa"."assigned_at")) AS "days_assigned"
   FROM (("inventory"."asset_assignments" "aa"
     JOIN "inventory"."assets" "a" ON (("a"."id" = "aa"."asset_id")))
     LEFT JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = "a"."catalog_item_id")))
  WHERE ("aa"."returned_at" IS NULL);


ALTER VIEW "inventory"."v_assets_assigned" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_assets_assigned" IS 'Currently assigned assets with custody details';



CREATE OR REPLACE VIEW "inventory"."v_on_hand_by_item_location" AS
 SELECT "tenant_id",
    "catalog_item_id",
    "location_id",
    "sum"("quantity_delta") AS "qty_on_hand",
    "max"("occurred_at") AS "last_movement_at"
   FROM "inventory"."stock_movements"
  GROUP BY "tenant_id", "catalog_item_id", "location_id"
 HAVING ("sum"("quantity_delta") <> (0)::numeric);


ALTER VIEW "inventory"."v_on_hand_by_item_location" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_on_hand_by_item_location" IS 'Current on-hand quantity derived from stock_movements ledger';



CREATE OR REPLACE VIEW "inventory"."v_reserved_by_item_location" AS
 SELECT "tenant_id",
    "catalog_item_id",
    "location_id",
    "sum"("qty") AS "qty_reserved",
    "count"(*) AS "reservation_count"
   FROM "inventory"."reservations"
  WHERE ("status" = 'active'::"text")
  GROUP BY "tenant_id", "catalog_item_id", "location_id";


ALTER VIEW "inventory"."v_reserved_by_item_location" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_reserved_by_item_location" IS 'Total reserved quantity from active reservations';



CREATE OR REPLACE VIEW "inventory"."v_available_by_item_location" AS
 SELECT COALESCE("oh"."tenant_id", "res"."tenant_id") AS "tenant_id",
    COALESCE("oh"."catalog_item_id", "res"."catalog_item_id") AS "catalog_item_id",
    COALESCE("oh"."location_id", "res"."location_id") AS "location_id",
    COALESCE("oh"."qty_on_hand", (0)::numeric) AS "qty_on_hand",
    COALESCE("res"."qty_reserved", (0)::numeric) AS "qty_reserved",
    (COALESCE("oh"."qty_on_hand", (0)::numeric) - COALESCE("res"."qty_reserved", (0)::numeric)) AS "qty_available",
    "oh"."last_movement_at"
   FROM ("inventory"."v_on_hand_by_item_location" "oh"
     FULL JOIN "inventory"."v_reserved_by_item_location" "res" ON ((("oh"."tenant_id" = "res"."tenant_id") AND ("oh"."catalog_item_id" = "res"."catalog_item_id") AND ("oh"."location_id" = "res"."location_id"))));


ALTER VIEW "inventory"."v_available_by_item_location" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_available_by_item_location" IS 'Available quantity = on_hand - reserved';



CREATE OR REPLACE VIEW "inventory"."v_on_order_by_item_location" AS
 SELECT "pol"."tenant_id",
    "pol"."catalog_item_id",
    "po"."delivery_location_id" AS "location_id",
    "sum"(("pol"."qty_ordered" - "pol"."qty_received")) AS "qty_on_order",
    "count"(DISTINCT "po"."id") AS "po_count",
    "min"("po"."expected_delivery_date") AS "earliest_expected_date"
   FROM ("supply_chain"."purchase_order_lines" "pol"
     JOIN "supply_chain"."purchase_orders" "po" ON (("pol"."po_id" = "po"."id")))
  WHERE (("po"."status" <> ALL (ARRAY['cancelled'::"text", 'closed'::"text"])) AND ("pol"."status" <> ALL (ARRAY['cancelled'::"text", 'received'::"text"])) AND (("pol"."qty_ordered" - "pol"."qty_received") > (0)::numeric))
  GROUP BY "pol"."tenant_id", "pol"."catalog_item_id", "po"."delivery_location_id";


ALTER VIEW "inventory"."v_on_order_by_item_location" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_on_order_by_item_location" IS 'Quantity on open POs not yet received';



CREATE OR REPLACE VIEW "inventory"."v_core_quantities" AS
 SELECT COALESCE("pos"."tenant_id", "oh"."tenant_id", "res"."tenant_id", "oo"."tenant_id") AS "tenant_id",
    COALESCE("pos"."catalog_item_id", "oh"."catalog_item_id", "res"."catalog_item_id", "oo"."catalog_item_id") AS "catalog_item_id",
    "i"."sku",
    "i"."name" AS "item_name",
    COALESCE("pos"."location_id", "oh"."location_id", "res"."location_id", "oo"."location_id") AS "location_id",
    "l"."name" AS "location_name",
    COALESCE("oh"."qty_on_hand", (0)::numeric) AS "qty_on_hand",
    COALESCE("res"."qty_reserved", (0)::numeric) AS "qty_reserved",
    (COALESCE("oh"."qty_on_hand", (0)::numeric) - COALESCE("res"."qty_reserved", (0)::numeric)) AS "qty_available",
    COALESCE("oo"."qty_on_order", (0)::numeric) AS "qty_on_order",
    ((COALESCE("oh"."qty_on_hand", (0)::numeric) - COALESCE("res"."qty_reserved", (0)::numeric)) + COALESCE("oo"."qty_on_order", (0)::numeric)) AS "inventory_position",
    "oh"."last_movement_at",
    "oo"."earliest_expected_date",
    "res"."reservation_count",
    "oo"."po_count"
   FROM (((((( SELECT DISTINCT "base"."tenant_id",
            "base"."catalog_item_id",
            "base"."location_id"
           FROM ( SELECT "v_on_hand_by_item_location"."tenant_id",
                    "v_on_hand_by_item_location"."catalog_item_id",
                    "v_on_hand_by_item_location"."location_id"
                   FROM "inventory"."v_on_hand_by_item_location"
                UNION
                 SELECT "v_reserved_by_item_location"."tenant_id",
                    "v_reserved_by_item_location"."catalog_item_id",
                    "v_reserved_by_item_location"."location_id"
                   FROM "inventory"."v_reserved_by_item_location"
                UNION
                 SELECT "v_on_order_by_item_location"."tenant_id",
                    "v_on_order_by_item_location"."catalog_item_id",
                    "v_on_order_by_item_location"."location_id"
                   FROM "inventory"."v_on_order_by_item_location") "base") "pos"
     LEFT JOIN "inventory"."v_on_hand_by_item_location" "oh" ON ((("pos"."tenant_id" = "oh"."tenant_id") AND ("pos"."catalog_item_id" = "oh"."catalog_item_id") AND ("pos"."location_id" = "oh"."location_id"))))
     LEFT JOIN "inventory"."v_reserved_by_item_location" "res" ON ((("pos"."tenant_id" = "res"."tenant_id") AND ("pos"."catalog_item_id" = "res"."catalog_item_id") AND ("pos"."location_id" = "res"."location_id"))))
     LEFT JOIN "inventory"."v_on_order_by_item_location" "oo" ON ((("pos"."tenant_id" = "oo"."tenant_id") AND ("pos"."catalog_item_id" = "oo"."catalog_item_id") AND ("pos"."location_id" = "oo"."location_id"))))
     LEFT JOIN "inventory"."catalog_items" "i" ON (("pos"."catalog_item_id" = "i"."id")))
     LEFT JOIN "inventory"."locations" "l" ON (("pos"."location_id" = "l"."id")));


ALTER VIEW "inventory"."v_core_quantities" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_core_quantities" IS 'Complete view of all 4 core quantities: on_hand, reserved, available, on_order + inventory position';



CREATE OR REPLACE VIEW "inventory"."v_current_abc_classification" AS
 WITH "latest_analysis" AS (
         SELECT DISTINCT ON ("abc_classification"."tenant_id", "abc_classification"."catalog_item_id") "abc_classification"."id",
            "abc_classification"."tenant_id",
            "abc_classification"."catalog_item_id",
            "abc_classification"."classification",
            "abc_classification"."annual_usage_qty",
            "abc_classification"."annual_usage_value",
            "abc_classification"."cumulative_value_pct",
            "abc_classification"."classification_method",
            "abc_classification"."value_rank",
            "abc_classification"."usage_rank",
            "abc_classification"."analysis_start_date",
            "abc_classification"."analysis_end_date",
            "abc_classification"."notes",
            "abc_classification"."created_at",
            "abc_classification"."updated_at",
            "abc_classification"."created_by",
            "abc_classification"."updated_by"
           FROM "inventory"."abc_classification"
          ORDER BY "abc_classification"."tenant_id", "abc_classification"."catalog_item_id", "abc_classification"."analysis_end_date" DESC
        )
 SELECT "la"."tenant_id",
    "la"."catalog_item_id",
    "ci"."sku",
    "ci"."name" AS "item_name",
    "la"."classification",
    "la"."annual_usage_qty",
    "la"."annual_usage_value",
    "la"."cumulative_value_pct",
    "la"."classification_method",
    "la"."value_rank",
    "la"."usage_rank",
    "la"."analysis_end_date",
        CASE "la"."classification"
            WHEN 'A'::"text" THEN 'High priority: Tight control, frequent reviews, accurate forecasting'::"text"
            WHEN 'B'::"text" THEN 'Medium priority: Regular monitoring, standard controls'::"text"
            WHEN 'C'::"text" THEN 'Low priority: Simple controls, bulk ordering'::"text"
            WHEN 'D'::"text" THEN 'Very low: Consider discontinuation or consignment'::"text"
            ELSE NULL::"text"
        END AS "management_strategy",
        CASE "la"."classification"
            WHEN 'A'::"text" THEN 'Weekly'::"text"
            WHEN 'B'::"text" THEN 'Monthly'::"text"
            WHEN 'C'::"text" THEN 'Quarterly'::"text"
            WHEN 'D'::"text" THEN 'Annually'::"text"
            ELSE NULL::"text"
        END AS "review_frequency"
   FROM ("latest_analysis" "la"
     JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = "la"."catalog_item_id")))
  WHERE ("ci"."active" = true);


ALTER VIEW "inventory"."v_current_abc_classification" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_current_abc_classification" IS 'Shows the most recent ABC classification for each active item with management recommendations';



CREATE OR REPLACE VIEW "public"."events_outbox" AS
 SELECT "id",
    "event_type",
    "tenant_id",
    "payload",
    "created_at",
    "status",
    "retry_count" AS "attempts",
    "next_attempt_at",
    "locked_at",
    "locked_by",
    "last_attempt_at",
    "last_error" AS "error_message",
    "published_at"
   FROM "inventory"."events_outbox";


ALTER VIEW "public"."events_outbox" OWNER TO "postgres";


COMMENT ON VIEW "public"."events_outbox" IS 'Hub polling interface - exposes events for Command Center ingestion';



CREATE OR REPLACE VIEW "inventory"."v_events_pending" AS
 SELECT "id",
    "tenant_id",
    "event_type",
    "status",
    "created_at",
    EXTRACT(epoch FROM ("now"() - "created_at")) AS "age_seconds",
        CASE
            WHEN (EXTRACT(epoch FROM ("now"() - "created_at")) > (300)::numeric) THEN 'STUCK'::"text"
            WHEN (EXTRACT(epoch FROM ("now"() - "created_at")) > (60)::numeric) THEN 'DELAYED'::"text"
            ELSE 'OK'::"text"
        END AS "check_status"
   FROM "public"."events_outbox" "eo"
  WHERE ("published_at" IS NULL)
  ORDER BY "created_at";


ALTER VIEW "inventory"."v_events_pending" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_events_pending" IS 'Monitors outbox for stuck/delayed events (>60s = delayed, >300s = stuck)';



CREATE OR REPLACE VIEW "inventory"."v_events_stuck" AS
 SELECT "id",
    "tenant_id",
    "event_type",
    "status",
    "retry_count",
    "max_retries",
    "created_at",
    "last_retry_at",
    "error_message",
    (EXTRACT(epoch FROM ("now"() - "created_at")) / (60)::numeric) AS "age_minutes",
        CASE
            WHEN ("retry_count" >= "max_retries") THEN 'DEAD_LETTER'::"text"
            WHEN (EXTRACT(epoch FROM ("now"() - "created_at")) > (3600)::numeric) THEN 'STUCK'::"text"
            WHEN (EXTRACT(epoch FROM ("now"() - "created_at")) > (300)::numeric) THEN 'DELAYED'::"text"
            ELSE 'OK'::"text"
        END AS "health_status"
   FROM "inventory"."events_outbox"
  WHERE ("published_at" IS NULL)
  ORDER BY "created_at";


ALTER VIEW "inventory"."v_events_stuck" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_events_stuck" IS 'Monitors outbox events that are stuck, delayed, or exceeded retry limits';



CREATE OR REPLACE VIEW "inventory"."v_idempotency_coverage" AS
 SELECT "table_name",
    "has_tenant_id",
    "has_last_event_id",
    "has_unique_constraint",
        CASE
            WHEN ("requires_idempotency" AND "has_last_event_id" AND "has_unique_constraint") THEN '✅ COMPLIANT'::"text"
            WHEN ("requires_idempotency" AND (NOT "has_last_event_id")) THEN '❌ MISSING last_event_id'::"text"
            WHEN ("requires_idempotency" AND "has_last_event_id" AND (NOT "has_unique_constraint")) THEN '⚠️ MISSING UNIQUE constraint'::"text"
            WHEN (NOT "requires_idempotency") THEN '✓ Not required'::"text"
            ELSE '⚠️ UNKNOWN'::"text"
        END AS "compliance_status"
   FROM ( SELECT "c"."table_name",
            ("max"(
                CASE
                    WHEN (("c"."column_name")::"name" = 'tenant_id'::"name") THEN 1
                    ELSE 0
                END) = 1) AS "has_tenant_id",
            ("max"(
                CASE
                    WHEN (("c"."column_name")::"name" = 'last_event_id'::"name") THEN 1
                    ELSE 0
                END) = 1) AS "has_last_event_id",
            (EXISTS ( SELECT 1
                   FROM "information_schema"."table_constraints" "tc"
                  WHERE ((("tc"."table_schema")::"name" = 'inventory'::"name") AND (("tc"."table_name")::"name" = ("c"."table_name")::"name") AND (("tc"."constraint_type")::"text" = 'UNIQUE'::"text") AND (("tc"."constraint_name")::"name" ~~ '%last_event_id%'::"text")))) AS "has_unique_constraint",
            (("c"."table_name")::"name" = ANY (ARRAY['inventory_events'::"name", 'asset_events'::"name", 'procurement_events'::"name", 'stock_movements'::"name", 'reservations'::"name", 'receipts'::"name", 'purchase_orders'::"name", 'purchase_order_lines'::"name", 'cycle_counts'::"name", 'cycle_count_lines'::"name", 'transfers'::"name", 'transfer_lines'::"name", 'asset_assignments'::"name"])) AS "requires_idempotency"
           FROM "information_schema"."columns" "c"
          WHERE ((("c"."table_schema")::"name" = 'inventory'::"name") AND (("c"."table_name")::"name" !~~ 'v_%'::"text"))
          GROUP BY "c"."table_name") "subq"
  ORDER BY
        CASE
            WHEN ("requires_idempotency" AND "has_last_event_id" AND "has_unique_constraint") THEN '✅ COMPLIANT'::"text"
            WHEN ("requires_idempotency" AND (NOT "has_last_event_id")) THEN '❌ MISSING last_event_id'::"text"
            WHEN ("requires_idempotency" AND "has_last_event_id" AND (NOT "has_unique_constraint")) THEN '⚠️ MISSING UNIQUE constraint'::"text"
            WHEN (NOT "requires_idempotency") THEN '✓ Not required'::"text"
            ELSE '⚠️ UNKNOWN'::"text"
        END, "table_name";


ALTER VIEW "inventory"."v_idempotency_coverage" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_idempotency_coverage" IS 'Monitors idempotency key coverage across all inventory tables';



CREATE OR REPLACE VIEW "inventory"."v_idempotency_summary" AS
 SELECT 'purchase_order_lines'::"text" AS "table_name",
    "count"(*) AS "total_rows",
    "count"("purchase_order_lines"."last_event_id") AS "rows_with_event_id",
    ("count"(*) - "count"("purchase_order_lines"."last_event_id")) AS "rows_missing_event_id",
    "round"(((100.0 * ("count"("purchase_order_lines"."last_event_id"))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "coverage_pct"
   FROM "supply_chain"."purchase_order_lines"
UNION ALL
 SELECT 'cycle_counts'::"text" AS "table_name",
    "count"(*) AS "total_rows",
    "count"("cycle_counts"."last_event_id") AS "rows_with_event_id",
    ("count"(*) - "count"("cycle_counts"."last_event_id")) AS "rows_missing_event_id",
    "round"(((100.0 * ("count"("cycle_counts"."last_event_id"))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "coverage_pct"
   FROM "inventory"."cycle_counts"
UNION ALL
 SELECT 'cycle_count_lines'::"text" AS "table_name",
    "count"(*) AS "total_rows",
    "count"("cycle_count_lines"."last_event_id") AS "rows_with_event_id",
    ("count"(*) - "count"("cycle_count_lines"."last_event_id")) AS "rows_missing_event_id",
    "round"(((100.0 * ("count"("cycle_count_lines"."last_event_id"))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "coverage_pct"
   FROM "inventory"."cycle_count_lines"
UNION ALL
 SELECT 'transfers'::"text" AS "table_name",
    "count"(*) AS "total_rows",
    "count"("transfers"."last_event_id") AS "rows_with_event_id",
    ("count"(*) - "count"("transfers"."last_event_id")) AS "rows_missing_event_id",
    "round"(((100.0 * ("count"("transfers"."last_event_id"))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "coverage_pct"
   FROM "inventory"."transfers"
UNION ALL
 SELECT 'asset_assignments'::"text" AS "table_name",
    "count"(*) AS "total_rows",
    "count"("asset_assignments"."last_event_id") AS "rows_with_event_id",
    ("count"(*) - "count"("asset_assignments"."last_event_id")) AS "rows_missing_event_id",
    "round"(((100.0 * ("count"("asset_assignments"."last_event_id"))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "coverage_pct"
   FROM "inventory"."asset_assignments"
UNION ALL
 SELECT 'reservations'::"text" AS "table_name",
    "count"(*) AS "total_rows",
    "count"("reservations"."last_event_id") AS "rows_with_event_id",
    ("count"(*) - "count"("reservations"."last_event_id")) AS "rows_missing_event_id",
    "round"(((100.0 * ("count"("reservations"."last_event_id"))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "coverage_pct"
   FROM "inventory"."reservations";


ALTER VIEW "inventory"."v_idempotency_summary" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_idempotency_summary" IS 'Tracks last_event_id coverage across all tables requiring idempotency';



CREATE OR REPLACE VIEW "inventory"."v_inventory_position" AS
 SELECT COALESCE("avail"."tenant_id", "oo"."tenant_id") AS "tenant_id",
    COALESCE("avail"."catalog_item_id", "oo"."catalog_item_id") AS "catalog_item_id",
    COALESCE("avail"."location_id", "oo"."location_id") AS "location_id",
    COALESCE("avail"."qty_on_hand", (0)::numeric) AS "qty_on_hand",
    COALESCE("avail"."qty_reserved", (0)::numeric) AS "qty_reserved",
    COALESCE("avail"."qty_available", (0)::numeric) AS "qty_available",
    COALESCE("oo"."qty_on_order", (0)::numeric) AS "qty_on_order",
    ((COALESCE("avail"."qty_on_hand", (0)::numeric) - COALESCE("avail"."qty_reserved", (0)::numeric)) + COALESCE("oo"."qty_on_order", (0)::numeric)) AS "inventory_position",
    "avail"."last_movement_at",
    "oo"."earliest_expected_date"
   FROM ("inventory"."v_available_by_item_location" "avail"
     FULL JOIN "inventory"."v_on_order_by_item_location" "oo" ON ((("avail"."tenant_id" = "oo"."tenant_id") AND ("avail"."catalog_item_id" = "oo"."catalog_item_id") AND ("avail"."location_id" = "oo"."location_id"))));


ALTER VIEW "inventory"."v_inventory_position" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_inventory_position" IS 'Comprehensive inventory position: on_hand - reserved + on_order';



CREATE OR REPLACE VIEW "inventory"."v_item_status_summary" AS
 SELECT "tenant_id",
    "count"(*) AS "total_items",
    "count"(*) FILTER (WHERE (("active" = true) AND ("deprecated" = false))) AS "active_items",
    "count"(*) FILTER (WHERE ("active" = false)) AS "inactive_items",
    "count"(*) FILTER (WHERE ("deprecated" = true)) AS "deprecated_items",
    "count"(*) FILTER (WHERE ("seasonal" = true)) AS "seasonal_items",
    "count"(*) FILTER (WHERE ("reorder_point" IS NOT NULL)) AS "items_with_reorder_point"
   FROM "inventory"."catalog_items"
  GROUP BY "tenant_id";


ALTER VIEW "inventory"."v_item_status_summary" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_item_status_summary" IS 'Summary of catalog item statuses by tenant';



CREATE OR REPLACE VIEW "inventory"."v_items_below_par" AS
 SELECT "pl"."tenant_id",
    "pl"."catalog_item_id",
    "ci"."sku",
    "ci"."name",
    "pl"."location_id",
    "l"."name" AS "location_name",
    COALESCE("sb"."qty_on_hand", (0)::numeric) AS "qty_on_hand",
    COALESCE("sb"."qty_available", (0)::numeric) AS "qty_available",
    "pl"."min_qty",
    "pl"."max_qty",
    "pl"."reorder_point",
    "pl"."safety_stock",
    ("pl"."min_qty" - COALESCE("sb"."qty_on_hand", (0)::numeric)) AS "qty_below_min",
        CASE
            WHEN (("pl"."reorder_point" IS NOT NULL) AND (COALESCE("sb"."qty_on_hand", (0)::numeric) <= "pl"."reorder_point")) THEN 'REORDER'::"text"
            WHEN (COALESCE("sb"."qty_on_hand", (0)::numeric) < "pl"."min_qty") THEN 'BELOW_MIN'::"text"
            ELSE 'OK'::"text"
        END AS "status"
   FROM ((("inventory"."item_location_par_levels" "pl"
     JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = "pl"."catalog_item_id")))
     JOIN "inventory"."locations" "l" ON (("l"."id" = "pl"."location_id")))
     LEFT JOIN "inventory"."stock_balances" "sb" ON ((("sb"."catalog_item_id" = "pl"."catalog_item_id") AND ("sb"."location_id" = "pl"."location_id") AND ("sb"."tenant_id" = "pl"."tenant_id"))))
  WHERE (("pl"."active" = true) AND ((("pl"."reorder_point" IS NOT NULL) AND (COALESCE("sb"."qty_on_hand", (0)::numeric) <= "pl"."reorder_point")) OR (COALESCE("sb"."qty_on_hand", (0)::numeric) < "pl"."min_qty")));


ALTER VIEW "inventory"."v_items_below_par" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_items_below_par" IS 'Items currently below their par levels (triggers restocking/reordering)';



CREATE OR REPLACE VIEW "inventory"."v_items_needing_reorder" AS
 SELECT "sb"."tenant_id",
    "sb"."catalog_item_id",
    "sb"."location_id",
    "ci"."sku",
    "ci"."name" AS "item_name",
    "l"."name" AS "location_name",
    "sb"."qty_on_hand",
    "sb"."qty_reserved",
    "sb"."qty_available",
    COALESCE("oo"."qty_on_order", (0)::numeric) AS "qty_on_order",
    ("sb"."qty_available" + COALESCE("oo"."qty_on_order", (0)::numeric)) AS "inventory_position",
    COALESCE("ilp"."reorder_point", "ci"."reorder_point", (0)::numeric) AS "reorder_point",
    COALESCE("ilp"."min_qty", "ci"."min_stock_level", (0)::numeric) AS "min_stock_level",
    COALESCE("ilp"."max_qty", "ci"."target_level", (0)::numeric) AS "target_level",
    COALESCE("ci"."reorder_qty", (0)::numeric) AS "reorder_qty",
    "ci"."lead_time_days",
    "ci"."preferred_vendor_id",
        CASE
            WHEN ("sb"."qty_available" <= (0)::numeric) THEN 'critical'::"text"
            WHEN (("sb"."qty_available" + COALESCE("oo"."qty_on_order", (0)::numeric)) <= COALESCE("ilp"."min_qty", "ci"."min_stock_level", (0)::numeric)) THEN 'high'::"text"
            WHEN (("sb"."qty_available" + COALESCE("oo"."qty_on_order", (0)::numeric)) <= COALESCE("ilp"."reorder_point", "ci"."reorder_point", (0)::numeric)) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "alert_priority",
        CASE
            WHEN ("sb"."qty_available" <= (0)::numeric) THEN 'stockout'::"text"
            WHEN (("sb"."qty_available" + COALESCE("oo"."qty_on_order", (0)::numeric)) <= COALESCE("ilp"."min_qty", "ci"."min_stock_level", (0)::numeric)) THEN 'below_min'::"text"
            WHEN (("sb"."qty_available" + COALESCE("oo"."qty_on_order", (0)::numeric)) <= COALESCE("ilp"."reorder_point", "ci"."reorder_point", (0)::numeric)) THEN 'below_reorder'::"text"
            ELSE NULL::"text"
        END AS "alert_type",
    GREATEST((COALESCE("ilp"."max_qty", "ci"."target_level", (0)::numeric) - ("sb"."qty_available" + COALESCE("oo"."qty_on_order", (0)::numeric))), COALESCE("ci"."reorder_qty", (0)::numeric)) AS "suggested_order_qty"
   FROM (((("inventory"."stock_balances" "sb"
     JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = "sb"."catalog_item_id")))
     JOIN "inventory"."locations" "l" ON (("l"."id" = "sb"."location_id")))
     LEFT JOIN "inventory"."item_location_par_levels" "ilp" ON ((("ilp"."catalog_item_id" = "sb"."catalog_item_id") AND ("ilp"."location_id" = "sb"."location_id"))))
     LEFT JOIN "inventory"."v_on_order_by_item_location" "oo" ON ((("oo"."catalog_item_id" = "sb"."catalog_item_id") AND ("oo"."location_id" = "sb"."location_id"))))
  WHERE (("ci"."active" = true) AND ("ci"."tracking_mode" = ANY (ARRAY['stock'::"text", 'both'::"text"])) AND ((("sb"."qty_available" + COALESCE("oo"."qty_on_order", (0)::numeric)) <= COALESCE("ilp"."reorder_point", "ci"."reorder_point", (0)::numeric)) OR ("sb"."qty_available" <= (0)::numeric)));


ALTER VIEW "inventory"."v_items_needing_reorder" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_items_needing_reorder" IS 'Shows items that have fallen below reorder points or are stocked out. Includes suggested order quantities.';



CREATE OR REPLACE VIEW "inventory"."v_ledger_balance_reconciliation" AS
 WITH "ledger_totals" AS (
         SELECT "stock_movements"."tenant_id",
            "stock_movements"."catalog_item_id",
            "stock_movements"."location_id",
            "sum"("stock_movements"."quantity_delta") AS "ledger_qty"
           FROM "inventory"."stock_movements"
          GROUP BY "stock_movements"."tenant_id", "stock_movements"."catalog_item_id", "stock_movements"."location_id"
        )
 SELECT COALESCE("lt"."tenant_id", "sb"."tenant_id") AS "tenant_id",
    COALESCE("lt"."catalog_item_id", "sb"."catalog_item_id") AS "catalog_item_id",
    "ci"."sku",
    "ci"."name" AS "item_name",
    COALESCE("lt"."location_id", "sb"."location_id") AS "location_id",
    "l"."name" AS "location_name",
    COALESCE("lt"."ledger_qty", (0)::numeric) AS "ledger_qty",
    COALESCE("sb"."qty_on_hand", (0)::numeric) AS "balance_qty",
    (COALESCE("lt"."ledger_qty", (0)::numeric) - COALESCE("sb"."qty_on_hand", (0)::numeric)) AS "variance",
        CASE
            WHEN (COALESCE("lt"."ledger_qty", (0)::numeric) = COALESCE("sb"."qty_on_hand", (0)::numeric)) THEN 'OK'::"text"
            ELSE 'MISMATCH'::"text"
        END AS "status"
   FROM ((("ledger_totals" "lt"
     FULL JOIN "inventory"."stock_balances" "sb" ON ((("sb"."tenant_id" = "lt"."tenant_id") AND ("sb"."catalog_item_id" = "lt"."catalog_item_id") AND ("sb"."location_id" = "lt"."location_id"))))
     LEFT JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = COALESCE("lt"."catalog_item_id", "sb"."catalog_item_id"))))
     LEFT JOIN "inventory"."locations" "l" ON (("l"."id" = COALESCE("lt"."location_id", "sb"."location_id"))))
  WHERE (COALESCE("lt"."ledger_qty", (0)::numeric) <> COALESCE("sb"."qty_on_hand", (0)::numeric));


ALTER VIEW "inventory"."v_ledger_balance_reconciliation" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_ledger_balance_reconciliation" IS 'Identifies mismatches between ledger and balance tables';



CREATE OR REPLACE VIEW "inventory"."v_po_status_summary" AS
 SELECT "po"."tenant_id",
    "po"."status",
    "count"(DISTINCT "po"."id") AS "po_count",
    "count"("pol"."id") AS "total_lines",
    "sum"("pol"."qty_ordered") AS "total_qty_ordered",
    "sum"("pol"."qty_received") AS "total_qty_received",
    "sum"(("pol"."qty_ordered" - "pol"."qty_received")) AS "total_qty_outstanding"
   FROM ("supply_chain"."purchase_orders" "po"
     LEFT JOIN "supply_chain"."purchase_order_lines" "pol" ON (("po"."id" = "pol"."po_id")))
  GROUP BY "po"."tenant_id", "po"."status";


ALTER VIEW "inventory"."v_po_status_summary" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_po_status_summary" IS 'Summary of purchase orders by status';



CREATE TABLE IF NOT EXISTS "supply_chain"."vendor_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "vendor_id" "uuid" NOT NULL,
    "catalog_item_id" "uuid" NOT NULL,
    "vendor_sku" "text" NOT NULL,
    "vendor_uom" "text",
    "pack_size" numeric(18,4) DEFAULT 1,
    "is_preferred" boolean DEFAULT false,
    "unit_cost" numeric(18,4),
    "currency" "text" DEFAULT 'USD'::"text",
    "lead_time_days" integer,
    "min_order_qty" numeric(18,4),
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "supply_chain"."vendor_items" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."vendor_items" IS 'Maps catalog items to vendor SKUs for auto-ordering';



CREATE TABLE IF NOT EXISTS "supply_chain"."vendors" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "code" "text",
    "contact_name" "text",
    "contact_email" "text",
    "contact_phone" "text",
    "payment_terms" "text",
    "notes" "text",
    "active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lead_time_days" integer
);


ALTER TABLE "supply_chain"."vendors" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."vendors" IS 'Vendor/supplier master data';



COMMENT ON COLUMN "supply_chain"."vendors"."lead_time_days" IS 'Expected lead time in days for deliveries from this vendor';



CREATE OR REPLACE VIEW "inventory"."v_reorder_suggestions" AS
 SELECT "i"."tenant_id",
    "i"."id" AS "catalog_item_id",
    "i"."sku",
    "i"."name",
    "i"."reorder_point",
    "i"."reorder_qty",
    "i"."target_level",
    "i"."pack_size",
    "i"."preferred_vendor_id",
    "i"."lead_time_days",
    "pos"."location_id",
    "pos"."inventory_position",
    "pos"."qty_on_hand",
    "pos"."qty_reserved",
    "pos"."qty_on_order",
        CASE
            WHEN ("i"."target_level" IS NOT NULL) THEN GREATEST((0)::numeric, ("ceil"((("i"."target_level" - "pos"."inventory_position") / "i"."pack_size")) * "i"."pack_size"))
            WHEN ("i"."reorder_qty" IS NOT NULL) THEN ("ceil"(("i"."reorder_qty" / "i"."pack_size")) * "i"."pack_size")
            ELSE ("ceil"(((("i"."reorder_point" * (2)::numeric) - "pos"."inventory_position") / "i"."pack_size")) * "i"."pack_size")
        END AS "suggested_order_qty",
    "v"."name" AS "preferred_vendor_name",
    "vi"."vendor_sku",
    "vi"."unit_cost" AS "estimated_unit_cost",
    "pos"."earliest_expected_date" AS "next_expected_receipt"
   FROM ((("inventory"."catalog_items" "i"
     LEFT JOIN "inventory"."v_inventory_position" "pos" ON ((("i"."tenant_id" = "pos"."tenant_id") AND ("i"."id" = "pos"."catalog_item_id"))))
     LEFT JOIN "supply_chain"."vendors" "v" ON (("i"."preferred_vendor_id" = "v"."id")))
     LEFT JOIN "supply_chain"."vendor_items" "vi" ON ((("i"."id" = "vi"."catalog_item_id") AND ("i"."preferred_vendor_id" = "vi"."vendor_id"))))
  WHERE (("i"."active" = true) AND ("i"."reorder_point" IS NOT NULL) AND (COALESCE("pos"."inventory_position", (0)::numeric) <= "i"."reorder_point"));


ALTER VIEW "inventory"."v_reorder_suggestions" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_reorder_suggestions" IS 'Items below reorder point with suggested order quantities';



CREATE OR REPLACE VIEW "inventory"."v_reservation_integrity" AS
 WITH "reservation_totals" AS (
         SELECT "reservations"."tenant_id",
            "reservations"."catalog_item_id",
            "reservations"."location_id",
            "sum"("reservations"."qty") AS "total_reserved"
           FROM "inventory"."reservations"
          WHERE ("reservations"."status" = 'active'::"text")
          GROUP BY "reservations"."tenant_id", "reservations"."catalog_item_id", "reservations"."location_id"
        )
 SELECT "rt"."tenant_id",
    "rt"."catalog_item_id",
    "ci"."sku",
    "ci"."name" AS "item_name",
    "rt"."location_id",
    "l"."name" AS "location_name",
    "rt"."total_reserved" AS "calculated_reserved",
    "sb"."qty_reserved" AS "balance_reserved",
    "sb"."qty_on_hand",
    ("rt"."total_reserved" - COALESCE("sb"."qty_reserved", (0)::numeric)) AS "variance",
        CASE
            WHEN ("rt"."total_reserved" > "sb"."qty_on_hand") THEN 'OVER_RESERVED'::"text"
            WHEN ("rt"."total_reserved" <> COALESCE("sb"."qty_reserved", (0)::numeric)) THEN 'MISMATCH'::"text"
            ELSE 'OK'::"text"
        END AS "status"
   FROM ((("reservation_totals" "rt"
     LEFT JOIN "inventory"."stock_balances" "sb" ON ((("sb"."tenant_id" = "rt"."tenant_id") AND ("sb"."catalog_item_id" = "rt"."catalog_item_id") AND ("sb"."location_id" = "rt"."location_id"))))
     LEFT JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = "rt"."catalog_item_id")))
     LEFT JOIN "inventory"."locations" "l" ON (("l"."id" = "rt"."location_id")))
  WHERE (("rt"."total_reserved" > COALESCE("sb"."qty_on_hand", (0)::numeric)) OR ("rt"."total_reserved" <> COALESCE("sb"."qty_reserved", (0)::numeric)));


ALTER VIEW "inventory"."v_reservation_integrity" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_reservation_integrity" IS 'Identifies reservation integrity issues (over-reserved or mismatched)';



CREATE OR REPLACE VIEW "inventory"."v_reservation_status_summary" AS
 SELECT "tenant_id",
    "status",
    "count"(*) AS "reservation_count",
    "sum"("qty") AS "total_qty_reserved",
    "count"(*) FILTER (WHERE ("needed_by" < CURRENT_DATE)) AS "overdue_count"
   FROM "inventory"."reservations"
  GROUP BY "tenant_id", "status";


ALTER VIEW "inventory"."v_reservation_status_summary" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_reservation_status_summary" IS 'Summary of reservations by status';



CREATE OR REPLACE VIEW "inventory"."v_reservations_expired" AS
 SELECT "r"."id",
    "r"."tenant_id",
    "r"."catalog_item_id",
    "ci"."sku",
    "ci"."name" AS "item_name",
    "r"."location_id",
    "l"."name" AS "location_name",
    "r"."qty",
    "r"."expiration_date",
    "r"."job_ref",
    "r"."external_order_ref",
    (CURRENT_DATE - "r"."expiration_date") AS "days_overdue"
   FROM (("inventory"."reservations" "r"
     JOIN "inventory"."catalog_items" "ci" ON (("ci"."id" = "r"."catalog_item_id")))
     JOIN "inventory"."locations" "l" ON (("l"."id" = "r"."location_id")))
  WHERE (("r"."status" = 'active'::"text") AND ("r"."expiration_date" IS NOT NULL) AND ("r"."expiration_date" < CURRENT_DATE));


ALTER VIEW "inventory"."v_reservations_expired" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_reservations_expired" IS 'Reservations that have passed their expiration date and need cancellation';



CREATE OR REPLACE VIEW "inventory"."v_rls_coverage" AS
 SELECT "schemaname",
    "tablename",
    "rowsecurity" AS "rls_enabled",
    ( SELECT "count"(*) AS "count"
           FROM "pg_policies"
          WHERE (("pg_policies"."schemaname" = "pt"."schemaname") AND ("pg_policies"."tablename" = "pt"."tablename"))) AS "policy_count"
   FROM "pg_tables" "pt"
  WHERE ("schemaname" = 'inventory'::"name")
  ORDER BY "rowsecurity" DESC, "tablename";


ALTER VIEW "inventory"."v_rls_coverage" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_rls_coverage" IS 'Shows RLS status and policy count for all inventory tables';



CREATE OR REPLACE VIEW "inventory"."v_table_bloat" AS
 SELECT "t"."schemaname",
    "t"."tablename",
    "pg_size_pretty"("pg_total_relation_size"((((("t"."schemaname")::"text" || '.'::"text") || ("t"."tablename")::"text"))::"regclass")) AS "total_size",
    "pg_size_pretty"("pg_relation_size"((((("t"."schemaname")::"text" || '.'::"text") || ("t"."tablename")::"text"))::"regclass")) AS "table_size",
    "pg_size_pretty"("pg_indexes_size"((((("t"."schemaname")::"text" || '.'::"text") || ("t"."tablename")::"text"))::"regclass")) AS "indexes_size",
    "pg_stat_get_live_tuples"("c"."oid") AS "live_tuples",
    "pg_stat_get_dead_tuples"("c"."oid") AS "dead_tuples",
        CASE
            WHEN ("pg_stat_get_live_tuples"("c"."oid") > 0) THEN "round"(((100.0 * ("pg_stat_get_dead_tuples"("c"."oid"))::numeric) / ("pg_stat_get_live_tuples"("c"."oid"))::numeric), 2)
            ELSE (0)::numeric
        END AS "dead_tuple_percent",
    "pg_stat_get_last_vacuum_time"("c"."oid") AS "last_vacuum",
    "pg_stat_get_last_autovacuum_time"("c"."oid") AS "last_autovacuum"
   FROM ("pg_tables" "t"
     JOIN "pg_class" "c" ON ((("c"."relname" = "t"."tablename") AND ("c"."relnamespace" = ( SELECT "pg_namespace"."oid"
           FROM "pg_namespace"
          WHERE ("pg_namespace"."nspname" = "t"."schemaname"))))))
  WHERE ("t"."schemaname" = 'inventory'::"name")
  ORDER BY ("pg_total_relation_size"((((("t"."schemaname")::"text" || '.'::"text") || ("t"."tablename")::"text"))::"regclass")) DESC;


ALTER VIEW "inventory"."v_table_bloat" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_table_bloat" IS 'Monitors table bloat and vacuum activity';



CREATE TABLE IF NOT EXISTS "supply_chain"."vendor_performance_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "vendor_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "event_date" timestamp with time zone DEFAULT "now"() NOT NULL,
    "po_id" "uuid",
    "receipt_id" "uuid",
    "quantity" numeric(18,4),
    "amount" numeric(18,2),
    "days_late" integer,
    "expected_date" "date",
    "actual_date" "date",
    "metadata" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    CONSTRAINT "vendor_performance_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['po_created'::"text", 'po_cancelled'::"text", 'delivery_on_time'::"text", 'delivery_late'::"text", 'items_received'::"text", 'items_rejected'::"text", 'invoice_paid'::"text", 'dispute_raised'::"text", 'quality_issue_reported'::"text"])))
);


ALTER TABLE "supply_chain"."vendor_performance_events" OWNER TO "postgres";


CREATE OR REPLACE VIEW "inventory"."v_vendor_performance_summary" AS
 WITH "recent_period" AS (
         SELECT "vendor_performance_events"."vendor_id",
            "vendor_performance_events"."tenant_id",
            "count"(*) FILTER (WHERE ("vendor_performance_events"."event_type" = 'po_created'::"text")) AS "pos_created_90d",
            "sum"("vendor_performance_events"."amount") FILTER (WHERE ("vendor_performance_events"."event_type" = 'po_created'::"text")) AS "total_spend_90d",
            "count"(*) FILTER (WHERE ("vendor_performance_events"."event_type" = 'delivery_on_time'::"text")) AS "on_time_count",
            "count"(*) FILTER (WHERE ("vendor_performance_events"."event_type" = 'delivery_late'::"text")) AS "late_count",
            "avg"("vendor_performance_events"."days_late") FILTER (WHERE (("vendor_performance_events"."event_type" = 'delivery_late'::"text") AND ("vendor_performance_events"."days_late" > 0))) AS "avg_days_late",
            "sum"("vendor_performance_events"."quantity") FILTER (WHERE ("vendor_performance_events"."event_type" = 'items_received'::"text")) AS "total_items_received",
            "sum"("vendor_performance_events"."quantity") FILTER (WHERE ("vendor_performance_events"."event_type" = 'items_rejected'::"text")) AS "total_items_rejected",
            "count"(*) FILTER (WHERE ("vendor_performance_events"."event_type" = 'dispute_raised'::"text")) AS "disputes_count"
           FROM "supply_chain"."vendor_performance_events"
          WHERE ("vendor_performance_events"."event_date" >= (CURRENT_DATE - '90 days'::interval))
          GROUP BY "vendor_performance_events"."vendor_id", "vendor_performance_events"."tenant_id"
        )
 SELECT "v"."id" AS "vendor_id",
    "v"."tenant_id",
    "v"."name" AS "vendor_name",
    "v"."code" AS "vendor_code",
    "v"."active" AS "is_active",
    COALESCE("rp"."pos_created_90d", (0)::bigint) AS "pos_last_90_days",
    COALESCE("rp"."total_spend_90d", (0)::numeric) AS "spend_last_90_days",
        CASE
            WHEN ((COALESCE("rp"."on_time_count", (0)::bigint) + COALESCE("rp"."late_count", (0)::bigint)) > 0) THEN "round"(((COALESCE("rp"."on_time_count", (0)::bigint))::numeric / ((COALESCE("rp"."on_time_count", (0)::bigint) + COALESCE("rp"."late_count", (0)::bigint)))::numeric), 4)
            ELSE NULL::numeric
        END AS "on_time_delivery_rate",
    COALESCE("rp"."avg_days_late", (0)::numeric) AS "avg_days_late",
        CASE
            WHEN (COALESCE("rp"."total_items_received", (0)::numeric) > (0)::numeric) THEN "round"(((1)::numeric - (COALESCE("rp"."total_items_rejected", (0)::numeric) / "rp"."total_items_received")), 4)
            ELSE NULL::numeric
        END AS "quality_score",
    COALESCE("rp"."disputes_count", (0)::bigint) AS "disputes_last_90_days",
        CASE
            WHEN ((COALESCE("rp"."on_time_count", (0)::bigint) + COALESCE("rp"."late_count", (0)::bigint)) = 0) THEN NULL::numeric
            ELSE LEAST(5.0, GREATEST(1.0, (((5.0 - (((COALESCE("rp"."late_count", (0)::bigint))::numeric / (GREATEST((1)::bigint, (COALESCE("rp"."on_time_count", (0)::bigint) + COALESCE("rp"."late_count", (0)::bigint))))::numeric) * (2)::numeric)) - ((COALESCE("rp"."total_items_rejected", (0)::numeric) / GREATEST((1)::numeric, COALESCE("rp"."total_items_received", (1)::numeric))) * (2)::numeric)) - LEAST(1.0, ((COALESCE("rp"."disputes_count", (0)::bigint))::numeric * 0.5)))))
        END AS "overall_rating"
   FROM ("supply_chain"."vendors" "v"
     LEFT JOIN "recent_period" "rp" ON ((("rp"."vendor_id" = "v"."id") AND ("rp"."tenant_id" = "v"."tenant_id"))));


ALTER VIEW "inventory"."v_vendor_performance_summary" OWNER TO "postgres";


COMMENT ON VIEW "inventory"."v_vendor_performance_summary" IS 'Vendor performance summary based on last 90 days of activity';



