    CONSTRAINT "dashboards_scope_check" CHECK (((("scope" = 'role'::"text") AND ("role_key" IS NOT NULL)) OR (("scope" = 'user'::"text") AND ("owner_user_id" IS NOT NULL)) OR ("scope" = 'tenant'::"text"))),
    CONSTRAINT "dashboards_scope_enum_check" CHECK (("scope" = ANY (ARRAY['tenant'::"text", 'role'::"text", 'user'::"text"])))
);


