CREATE TABLE IF NOT EXISTS "public"."tenants" (
    "id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "slug" "text",
    "industry" "text",
    "address" "jsonb",
    "metadata" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "synced_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_event_id" "text"
);


ALTER TABLE "public"."tenants" OWNER TO "postgres";


COMMENT ON TABLE "public"."tenants" IS 'Tenant information synced from Summit One Core via webhooks';



COMMENT ON COLUMN "public"."tenants"."id" IS 'Tenant UUID from Core (matches session tenantId)';



COMMENT ON COLUMN "public"."tenants"."synced_at" IS 'Last time this record was updated from Core events';



COMMENT ON COLUMN "public"."tenants"."last_event_id" IS 'Event ID from Core service webhooks - ensures idempotent webhook processing';



CREATE TABLE IF NOT EXISTS "public"."widget_registry" (
    "widget_key" "text" NOT NULL,
    "domain" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "default_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "allowed_filters" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "is_enabled" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "default_width" integer DEFAULT 4 NOT NULL,
    "default_height" integer DEFAULT 4 NOT NULL
);


ALTER TABLE "public"."widget_registry" OWNER TO "postgres";


COMMENT ON TABLE "public"."widget_registry" IS 'Catalog of available widget types across all tenants';



COMMENT ON COLUMN "public"."widget_registry"."widget_key" IS 'Unique identifier for widget type (e.g., inventory.widget.items_below_reorder)';



COMMENT ON COLUMN "public"."widget_registry"."domain" IS 'Widget category: inventory, flow, procurement, alerts, exec';



COMMENT ON COLUMN "public"."widget_registry"."allowed_filters" IS 'List of configurable filter keys this widget supports';



COMMENT ON COLUMN "public"."widget_registry"."default_width" IS 'Default grid width (columns) when adding widget to dashboard';



COMMENT ON COLUMN "public"."widget_registry"."default_height" IS 'Default grid height (rows) when adding widget to dashboard';



CREATE TABLE IF NOT EXISTS "supply_chain"."accounting_expenses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "vendor_id" "uuid",
    "po_id" "uuid",
    "expense_date" "date" NOT NULL,
    "amount" numeric(18,4) NOT NULL,
    "currency" "text" DEFAULT 'USD'::"text",
    "status" "text" DEFAULT 'posted'::"text" NOT NULL,
    "receipt_url" "text",
    "invoice_number" "text",
    "description" "text",
    "matched_at" timestamp with time zone,
    "last_event_id" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "accounting_expenses_status_check" CHECK (("status" = ANY (ARRAY['posted'::"text", 'matched'::"text", 'disputed'::"text", 'ignored'::"text"])))
);


ALTER TABLE "supply_chain"."accounting_expenses" OWNER TO "postgres";


COMMENT ON TABLE "supply_chain"."accounting_expenses" IS 'Non-authoritative expense tracking for matching to POs';



CREATE TABLE IF NOT EXISTS "supply_chain"."procurement_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "po_id" "uuid",
    "actor_user_id" "uuid",
    "source_system" "text",
    "last_event_id" "text" NOT NULL,
    "payload" "jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "procurement_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['po_created'::"text", 'po_approved'::"text", 'po_cancelled'::"text", 'items_received'::"text", 'invoice_matched'::"text", 'payment_made'::"text"])))
);


ALTER TABLE "supply_chain"."procurement_events" OWNER TO "postgres";


