CREATE POLICY "purchase_orders_update_admin_or_draft" ON "supply_chain"."purchase_orders" FOR UPDATE USING ((("tenant_id" = ((("auth"."jwt"() -> 'app_metadata'::"text") ->> 'tenant_id'::"text"))::"uuid") AND (("status" = 'draft'::"text") OR ((("auth"."jwt"() -> 'app_metadata'::"text") ->> 'role'::"text") = 'admin'::"text"))));



