ALTER TABLE "supply_chain"."vendor_performance_events" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "vendor_performance_events_service_role" ON "supply_chain"."vendor_performance_events" TO "service_role" USING (true) WITH CHECK (true);



CREATE POLICY "vendor_performance_events_tenant_isolation_tenant_isolation" ON "supply_chain"."vendor_performance_events" USING (("tenant_id" = (("auth"."jwt"() ->> 'tenant_id'::"text"))::"uuid"));



ALTER TABLE "supply_chain"."vendor_performance_metrics" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "vendor_performance_metrics_service_role" ON "supply_chain"."vendor_performance_metrics" TO "service_role" USING (true) WITH CHECK (true);



